INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('4KxQkDxf56wC', 'Throne of Glass', array['Sarah J. Maas'], 2012, 'After serving out a year of hard labor in the salt mines of Endovier for her crimes, 18-year-old assassin Celaena Sardothien is dragged before the Crown Prince. Prince Dorian offers her her freedom on one condition: she must act as his champion in a competition to find a new royal assassin. Her opponents are men-thieves and assassins and warriors from across the empire, each sponsored by a member of the king''s council. If she beats her opponents in a series of eliminations, she''ll serve the kingdom for three years and then be granted her freedom. Celaena finds her training sessions with the captain of the guard, Westfall, challenging and exhilirating. But she''s bored stiff by court life. Things get a little more interesting when the prince starts to show interest in her... but it''s the gruff Captain Westfall who seems to understand her best. Then one of the other contestants turns up dead... quickly followed by another. Can Celaena figure out who the killer is before she becomes a victim? As the young assassin investigates, her search leads her to discover a greater destiny than she could possibly have imagined.', 'https://books.google.com/books/content?id=4KxQkDxf56wC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 419, 'http://play.google.com/books/reader?id=4KxQkDxf56wC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
