INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('oZE-1Nj8P6UC', 'New Spring', array['Robert Jordan'], 2004, 'From America''s premier fantasy writer---#1 New York Times and USA Today bestselling author of Crossroads of Twilight---comes an expanded version of his novella "New Spring," first published in the Legends collection. For three days battle has raged in the snow around the great city of Tar Valon. In the city, a Foretelling of the future is uttered. On the slopes of Dragonmount, the immense mountain that looms over the city, is born an infant prophesied to change the world. That child must be found before the forces of the Shadow have an opportunity to kill him. Moiraine Damodred, a young Accepted soon to be raised to Aes Sedai, and Lan Mandragoran, a soldier fighting in the battle, are set on paths that will bind their lives together. But those paths are filled with complications and dangers, for Moiraine, of the Royal House of Cairhien, whose king has just died, and Lan, considered the uncrowned king of a nation long dead, find their lives threatened by the plots of those seeking power. "New Spring" related some of these events, in compressed form; New Spring: The Novel tells the whole story.', 'https://books.google.com/books/content?id=oZE-1Nj8P6UC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 338, 'http://play.google.com/books/reader?id=oZE-1Nj8P6UC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
