INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('QLdNHVZo7MUC', 'Zahrah the Windseeker', array['Nnedi Okorafor','Nnedi Okorafor-Mbachu'], 2005, 'In the northern Ooni Kingdom, fear of the unknown runs deep, and children born dada are rumored to have special powers. Thirteen-year-old Zahrah Tsami feels like a normal girl--she grows her own flora computer, has mirrors sewn onto her clothes, and stays clear of the Forbidden Greeny Jungle. But unlike other children in the village of Kirki, Zahrah was born with the telling dadalocks. Only her best friend, Dari, isn''t afraid of her, even when something unusual begins happening--something that definitely makes Zahrah different. The two friends determine to investigate, edging closer and closer to danger. When Dari''s life is threatened, Zahrah must face her worst fears alone, including the very thing that makes her different. In this exciting debut novel by Nnedi Okorafor-Mbachu, things aren''t always what they seem--monkeys tell fortunes, plants offer wisdom, and a teenage girl is the only one who stands a chance at saving her best friend''s life.', 'https://books.google.com/books/content?id=QLdNHVZo7MUC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 332, 'http://play.google.com/books/reader?id=QLdNHVZo7MUC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
