INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('mICozwEACAAJ', 'The Tombs of Atuan', array['Ursula K. Le Guin'], 1984, 'THE TOMBS OF ATUAN Book Two of Ursula K. Le Guin''s Earthsea Cycle Now a SCI FI Original Miniseries! When young Tenar is chosen as high priestess to the ancient and nameless Powers of the Earth, everything is taken away from her-home, family, possessions, even her name. She is now known only as Arha, the Eaten One, guardian of the labyrinthine Tombs of Atuan, shrouded in darkness. When a young wizard, Ged Sparrowhawk, comes to steal the Tombs'' greatest hidden treasure, the Ring of Erreth-Akbe, Tenar''s rightful duty is to protect the Tombs. But Ged also brings with him the light of magic and tales of a brighter world Tenar has never known. Will Tenar risk everything to escape the darkness that has become her domain? With millions of copies sold worldwide, Ursula K. Le Guin''s Earthsea Cycle has earned a treasured place on the shelves of fantasy lovers everywhere, alongside the works of such beloved authors as J. R. R. Tolkien and C. S. Lewis.', 'https://books.google.com/books/content?id=mICozwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 'http://play.google.com/books/reader?id=mICozwEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
