INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('0MULAQAAMAAJ', 'The Tales of Beedle the Bard', array['J. K. Rowling'], 2008, '''And As For This Book,'' Said Hermione, The Tales Of Beedle The Bard... I&Rsquo;Ve Never Even Heard Of Them!'' ''You&Rsquo;Ve Never Heard Of The Tales Of Beedle The Bard?'' Said Ron Incredulously. ''You''Re Kidding, Right?'' (Taken From Harry Potter And The Deathly Hallows) Bloomsbury, In Association With The Children''S High Level Group, Is Delighted To Announce The Tales Of Beedle The Bard, The First New Book From J. K. Rowling Since The Publication Of The Final Book In The Harry Potter Series, Harry Potter And The Deathly Hallows. The Tales Of Beedle The Bard, Played A Crucial Role In Assisting Harry, Aided By His Friends Ron And Hermione, To Finally Defeat Lord Voldemort. Fans Will Be Thrilled To Have This Opportunity To Read The Tales In Full. The Tales Of Beedle The Bard Is Without Doubt An Exciting Addition To The Canon Of Harry Potter. They Also Reveal The Wonderful Versatility Of The Author, As She Tackles With Relish The Structure And Varying Tones Of A Classic Fairy Tale. There Are Five Tales Included In The Book: ''The Tale Of The Three Brothers'', Which Is Recounted In Harry Potter And The Deathly Hallows; Plus Four More &Mdash; ''The Fountain Of Fair Fortune'', ''The Warlock''S Hairy Heart'', ''The Wizard And The Hopping Pot'', And ''Babbitty Rabbitty And Her Cackling Stump''. Each Tale Has Its Own Magical Character And Will Variously Bring Delight, Laughter And The Thrill Of Mortal Peril. The Tales Of Beedle The Bard, Translated From The Original Runes By Hermione Granger, Is Introduced And Illustrated By J. K. Rowling. Also Included Are Notes On The Stories By Professor Albus Dumbledore, Which Appear By Generous Permission Of The Hogwarts Headmasters'' Archive.', 'https://books.google.com/books/content?id=0MULAQAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 136, 'http://play.google.com/books/reader?id=0MULAQAAMAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
