INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('E5khWQMmrTUC', 'Solaris', array['Stanisław Lem'], 1987, 'When psychologist Kris Kelvin arrives at the planet Solaris to study the ocean that covers its surface, he finds himself confronting a painful memory embodied in the physical likeness of a past lover. Kelvin learns that he is not alone in this and that other crews examining the planet are plagued with their own repressed and newly real memories. Could it be, as Solaris scientists speculate, that the ocean may be a massive neural center creating these memories, for a reason no one can identify?', 'https://books.google.com/books/content?id=E5khWQMmrTUC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 216, 'http://play.google.com/books/reader?id=E5khWQMmrTUC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
