INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('rXy_p0lY8u4C', 'The Boy Who Would Live Forever', array['Frederik Pohl'], 2004, 'In 1977 Frederik Pohl stunned the science fiction world with the publication of Gateway, one of the most brilliantly entertaining SF novels of all time. Gateway was a bestseller and won science fiction''s triple crown: the Hugo, Nebula, and John W. Campbell Memorial awards for best novel. Now, more than twenty-five years later, Pohl has completed a new novel set in the Gateway universe. The Boy Who Would Live Forever has a sense of wonder and excitement that will satisfy those who loved Gateway and will delight new readers as well. In Gateway, long after the alien Heechee abandoned their space-station, Gateway (as humans dubbed it) allowed humans to explore new worlds. The Heechee, alarmed by the alien Kugel whose goal was to destroy all organic lifeforms, had already retreated to the galactic core where they now lived in peace. Now, in The Boy Who Would Live Forever, humans with dreams of life among the stars are joining the Heechee at the core, to live there along with those humans and Heechee whose physical bodies have died and their minds stored in electronic memory so that their wisdom passes down through the ages. Their peace is threatened by the Kugel, who may yet attack the core. But a much greater threat is the human Wan Enrique Santos-Smith, whose blind loathing of the Heechee fuels an insane desire to destroy them and, incidentally, every living being in the galaxy. Stan and Estrella, two young people from Earth, went to Gateway looking for adventure, and found each other. They settle among the Heechee on Forested Planet of Warm Old Star Twenty-Four, never suspecting that they may be the last best hope to save the galaxy. But with allies like Gelle-Klara Moynlin--one of the galaxy''s richest women, who isn''t content to just have money, but wants to use her wealth for good, and machine mind Marc Antony-a wonderful chef to thousands of living and stored clients, they are destined to contend with Wan''s terrible plan. Frederik Pohl has woven together the lives of these and other memorable characters to create a masterful new novel.', 'https://books.google.com/books/content?id=rXy_p0lY8u4C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 482, 'http://play.google.com/books/reader?id=rXy_p0lY8u4C&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
