INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('76hiAAAAMAAJ', 'Night Watch', array['Sergei Lukyanenko'], 2006, 'The Night Watch series has caused a sensation never before seen in Russia -- its popularity is frenzied and unprecedented, and driven by a truly great, epic story. In 2005 Fox Searchlight announced it had acquired the Russian film adaptation for an American release. Interest in the books here is now set to reach a fever pitch. Set in modern day Moscow, Night Watch is a world as elaborate and imaginative as Tolkien or the best Asimov. Living among us are the "Others," an ancient race of humans with supernatural powers who swear allegiance to either the Dark or the Light. A thousand-year treaty has maintained the balance of power, and the two sides coexist in an uneasy truce. But an ancient prophecy decrees that one supreme "Other" will rise up and tip the balance, plunging the world into a catastrophic war between the Dark and the Light. When a young boy with extraordinary powers emerges, fulfilling the first half of the prophecy, will the forces of the Light be able to keep the Dark from corrupting the boy and destroying the world An extraordinary translation from the Russian by noted translator Andrew Bromfield, this first English language edition of Night Watch is a chilling, engrossing read certain to reward those waiting in anticipation of its arrival.', 'https://books.google.com/books/content?id=76hiAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 472, 'http://play.google.com/books/reader?id=76hiAAAAMAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
