INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('Pvz_EAAAQBAJ', 'The Girl by the Bridge', array['Arnaldur Indridason'], 2025, '18 million copies sold worldwide! An elderly couple are worried about their granddaughter. They know she''s been smuggling drugs, and now she''s gone missing. Looking for help, they turn to Konrad, a former policeman whose reputation precedes him. Always absent-minded, he constantly ruminates on the fate of his father, who was stabbed to death decades ago. But digging into the past reveals much more than anyone set out to discover, and a little girl who drowned in the Reykjavik city pond unexpectedly captures everyone''s attention. A brilliant, chilling tale of broken dreams and children who have nowhere to turn.', 'https://books.google.com/books/content?id=Pvz_EAAAQBAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 'http://play.google.com/books/reader?id=Pvz_EAAAQBAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
