INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('GDI60QEACAAJ', 'Murder at the Ponte Vecchio', array['T. A Williams'], 2025, 'Let bestselling author T.A. Williams whisk you away to gorgeous Tuscany in this cozy murder mystery featuring a retired DCI and his loyal companion, Oscar. �� It really is murder in paradise! An iconic bridge... �� Private investigator, Dan Armstrong, lives and works in Florence and knows the world famous Ponte Vecchio well. Usually a magnet for tourists, on this occasion it is the scene of an unexplained death, and Dan finds himself involved in the intriguing case. An uncompromising man... �� Dan quickly discovers that the victim, an elderly jeweller, was every bit as hard as the diamonds he sold in his shop on the bridge. Few people liked him, not even his adult children, and his business dealings look murkier than the waters of the River Arno. Dan suspects more secrets lie hidden...perhaps inside the massive safe in the old man''s luxury villa... A complex case. ���� As the evidence begins to mount up, so too do the suspects with their different motives. With a fortune in gold bullion and precious stones involved, Dan thinks the only way to catch the killer is to lay a trap, but might he be caught in the killer''s sights? Fortunately, he has Oscar, his canine wingman at his side, always eager to prove that he''s as good as gold. �� Can Dan and Oscar sniff out the killer''s tracks or will this case be a bridge too far? Praise for T A Williams: ''A fun mystery and a good read with descriptions of Portofino that made me want to go book a flight. Dan and Oscar are a great team and kept me guessing!'' Bestselling author Anita Davison ''T A Williams whisked me away to the beautiful Italian riviera in the company of an ex-pat private investigator and his gorgeous doggy sidekick on the case of a missing teacher. What a team, and what an adventure!!'' Bestselling author Kate Wells ''The perfect combination of character, setting and plot, heralding an addictive new cozy mystery series!'' Bestselling author Debbie Young ''Watching unassuming detective Dan Armstrong wheedle the truth out of folks is great fun. Highly Entertaining read!'' Bestselling author Kelly Oliver ''Dan and Oscar are great company in a sun-drenched mystery that keeps you guessing right till the end.'' Bestselling author Michelle Salter', 'https://books.google.com/books/content?id=GDI60QEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 'http://play.google.com/books/reader?id=GDI60QEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
