INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('EFzp0AEACAAJ', 'Who Killed the Rabbi''s Wife?', array['Saul Golubcow'], 2024, 'Frank Wolf, a Holocaust survivor turned private detective, returns to solve a chilling mystery in 1970s New York. When Batya Flaum, the wife of a prominent Brooklyn rabbi, is brutally murdered, no one is prepared for the shocking revelations that follow. Teaming up with his grandson Joel and Joel''s wife Aliya, Frank uncovers a web of secrets, deceit, and betrayal within the tight-knit Jewish community. As they navigate family dynamics and unravel long-buried truths, the trio must determine who is truly complicit in the crime . . . and why. Filled with suspense and psychological depth, this gripping novel challenges readers to confront moral dilemmas and question how well we really know those we love.', 'https://books.google.com/books/content?id=EFzp0AEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 'http://play.google.com/books/reader?id=EFzp0AEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
