INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('8SNCjwEACAAJ', 'Permanent Sunset', array['C. Michele Dorsey'], 2016, 'Former television meteorologist Sabrina Salter''s new life in paradise was idyllic, sprinkled with new friendships, romance and a successful villa rental business, which just landed Villa Nirvana, the newest and most opulent villa in the Virgin Islands. But island life isn''t all sun and sand. During the villa''s opening weekend, Sabrina discovers the body of a bride murdered on the eve of her wedding to the villa owner. The case gives the police a new reason to scrutinize Sabrina and her business, which they suggest provides inadequate security for its guests and should lose its license. Unless Sabrina can show the bride''s murder was unrelated to her or her business, her life on St. John will be over before sundown. In order to clear her name and salvage her business, Sabrina dives into the deep end of an investigation riddled with infidelity, fraud, identity theft, and conspiracy inPermanent Sunset, the second in C. Michele Dorsey''s riveting mystery series.', 'https://books.google.com/books/content?id=8SNCjwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 272, 'http://play.google.com/books/reader?id=8SNCjwEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
