INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('RAZQrgEACAAJ', 'Murder on Sagebrush Lane', array['Patricia Smith Wood'], 2015, 'In this second Harrie McKinsey Mystery, Harrie goes out to retrieve her morning newspaper and she discovers a small child sitting next to her flower beds. The little girl''s pajamas and teddy bear are smeared with blood, and Harrie''s journey to find the child''s parents involves her in a grisly murder investigation. Before the week is over, there''s another murder, an attempted kidnapping, a race to uncover a plot to steal top-secret data, and an encounter with a desperate killer who intends to make Harrie his final victim.', 'https://books.google.com/books/content?id=RAZQrgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 256, 'http://play.google.com/books/reader?id=RAZQrgEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
