INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('nYt2swEACAAJ', 'Waste Water', array['Andrea Elena Ibez'], 2018, 'Love, lust and political intrigue in the Southwest draw Melinda Burroughs from her job as a Congressional aide in Washington, DC, to assist in a grassroots campaign in Tucson, Arizona to stop the conversion of effluent into drinking water. She knows a lot about organizing a winning campaign, a little about Greg Abelard who persuaded her to help him, and next to nothing about the issue. That doesn''t stop her from jumping in feet first until she is up to her neck in dirty tricks and double dealing in the desert. And the ride of her life.', 'https://books.google.com/books/content?id=nYt2swEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 198, 'http://play.google.com/books/reader?id=nYt2swEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
