INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('x8MetwEACAAJ', 'To Love and Be Wise', array['Josephine Tey'], 2018, 'When a young strikingly handsome photographer mysteriously disappears, it''s up to Inspector Alan Grant to discover whether he accidentally drowned, committed suicide, or met his death at the hands of one of his many female admirers. We are delighted to publish this classic book as part of our extensive Classic Library collection. Many of the books in our collection have been out of print for decades, and therefore have not been accessible to the general public. The aim of our publishing program is to facilitate rapid access to this vast reservoir of literature, and our view is that this is a significant literary work, which deserves to be brought back into print after many decades. The contents of the vast majority of titles in the Classic Library have been scanned from the original works. To ensure a high quality product, each title has been meticulously hand curated by our staff. Our philosophy has been guided by a desire to provide the reader with a book that is as close as possible to ownership of the original work. We hope that you will enjoy this wonderful classic work, and that for you it becomes an enriching experience.', 'https://books.google.com/books/content?id=x8MetwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 210, 'http://play.google.com/books/reader?id=x8MetwEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
