INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('m6580QEACAAJ', 'Numbers Don''t Lie', array['Jane Honeck'], 2025, '2025 Next Generation Indie Book Award Finalist - ThrillerWhen numbers don''t add up, the truth is buried deep within the books. Ellen Hartman, CPA, expects a tough meeting with long-time client and grieving father, Dr. Tom Reynolds, but nothing prepares her for the shock he delivers. After his 21-year-old son tragically dies at sea, Tom returns to work only to learn he''s been fired from the surgical practice he founded and led for three decades. When Ellen discovers she has also been dismissed as the practice''s accountant, she suspects something more sinister is at play. To complicate matters, Tom''s wife, Lucy, believes their son''s death wasn''t the accident it appears to be. As Ellen digs deeper, she uncovers a tangle of secrets that link the Reynolds'' personal tragedy to professional betrayal. While her quick-witted associate, Julie Benoit, investigates from the home front in Portland, Maine, Ellen and Lucy set out to uncover the truth aboard the very sailboat where the young man''s life was lost. As Ellen and Julie unravel a web of deception, they help Tom and Lucy confront their grief, rediscover the enduring power of love, and find justice in the most unexpected places. *This Second Edition of Numbers Don''t Lie has been newly released with a beautiful updated cover and an enhanced interior design. The heart and message of the book remain unchanged, but this edition is the most up-to-date version and the one we recommend for readers discovering it today.', 'https://books.google.com/books/content?id=m6580QEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 'http://play.google.com/books/reader?id=m6580QEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
