         VALUES ('bfg6vgAACAAJ', 'The Circle', array['M. J. Trow'], 2017, 'Matthew Grand and James Batchelor leave London on commission to investigate the death of Lafayette Baker, head of the US National Detective Police, and find no shortage of people who wanted him dead.', 'https://books.google.com/books/content?id=bfg6vgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 'http://play.google.com/books/reader?id=bfg6vgAACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
