INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('TqLLzwEACAAJ', 'Death in a Bygone Hue', array['Susan Van Kirk'], 2023, 'When Jill Madison returns to her hometown to become executive director of a new art center, she never would have dreamed unexpected secrets from the past would put her life in danger. When her parents'' old friend, and Jill''s mentor, Judge Ron Spivey, is murdered, he leaves behind more than a few secrets. His baffling will makes Jill a rich woman, if she survives the six-month probate period. She finds a target on her back when the judge''s estranged children return and form an unholy alliance with a local muckraking journalist who specializes in making up news. According to the judge''s will, if Jill dies, the family inherits. Jill and her best friend launch their own investigation, determined to find the judge''s killer. In the meantime, Jill must run her first national juried exhibit, launch a new seniors'' group, and move the weavers'' guild into the art center. Her arch nemesis and art center board president, Ivan Truelove III, watches her every move, determined to remove her if she makes a mistake. And, in between finding dead bodies, Jill may also discover a bit of romance with a newly arrived doctor in town, if she can live to enjoy it.', 'https://books.google.com/books/content?id=TqLLzwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 'http://play.google.com/books/reader?id=TqLLzwEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
