INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('zLI7zgEACAAJ', 'The Long Road Home: Large Print Hardcover Edition', array['Carolyn M. Bowen'], 2021, 'After a lifetime of being protected and sheltered by her parents, Kate''s life turn upside down after their sudden death. With nowhere else to turn, she ends up with her fiancé a conniving businessman who is well on his way to becoming a corrupt lawyer. At the same time, Kate''s father''s law firm houses more secrets than a politician''s hard drive. Later, she receives a shocking surprise when a long-lost half-brother enters her life. Can Kate rise to these challenges, discover the truth and re-emerge as a stronger, smarter version of herself? This is the large print edition of The Long Road Home, with a larger font / typeface for easier reading.', 'https://books.google.com/books/content?id=zLI7zgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 278, 'http://play.google.com/books/reader?id=zLI7zgEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
