INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('u3jloQEACAAJ', 'The Sound of Victory', array['Jim Stovall'], 2014, 'Jacob Dyer is one of the most compelling characters in modern fiction. After his successful launch in the inaugural novel, The Sound of Honor, Jacob Dyer is back in The Sound of Victory with his compelling assistant Monica and his stalwart limo driver Franklin. After losing his sight in Vietnam, Jacob Dyer retreated from his hopes and dreams and moved back to his hometown of Tulsa, Oklahoma. Just when he thought life might not be worth living, he discovered an unexpected lifeline as he founded Dyer Straits Lost and Found. He explains, "We are not investigators, not lawyers, and not anything else that''s easy to describe. We simply stumble around and find things that people have lost when they have nowhere else to turn." This time out, Jacob Dyer is stretched to the limit as he runs the race of his life and tries to save Monica as he realizes how much she means and that he simply can''t live without her. When all is dark and you can''t see a way out, you have to wait for the sound of victory.', 'https://books.google.com/books/content?id=u3jloQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 184, 'http://play.google.com/books/reader?id=u3jloQEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
