INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('gB3tsgEACAAJ', 'Bagger Island', array['Denis Hearn'], 2015, 'The trawler Girl Anne finds a body in its net off Bagger Island, located in the southeast of Ireland. Detective Conor Horgan, with his friend and reporter, Anne O''Gorman, arrive to investigate the strange catch. What is happening on Bagger Island? Who is Don Rua, its mysterious owner? Join Conor and Anne on the rocky island and cross the Channel into the caves of France, as they chase the clues and discover an underworld of hidden treasures and ruthless smugglers. Will their relationship survive?', 'https://books.google.com/books/content?id=gB3tsgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 304, 'http://play.google.com/books/reader?id=gB3tsgEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
