INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('wrtmngEACAAJ', 'North Murder Beach', array['Rodney Riesel'], 2014, 'North Murder Beach, by Rodney Riesel, is the first installment of the story of North Myrtle Beach police detective, Jake Stellar. The spring bike rallies have ended, the spring breakers have all gone back to school, and the summer tourist season is a few weeks away. What better time for a police officer to take a nice quiet relaxing week off from work? That''s what Jake Stellar had in mind. That is until someone from his past resurfaces to remind him of a terrible secret he has spent years trying to forget. In North Murder Beach, a story of revenge, Jake is unwillingly and violently forced to confront this secret from his past.', 'https://books.google.com/books/content?id=wrtmngEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 166, 'http://play.google.com/books/reader?id=wrtmngEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
