INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('Id9VLwEACAAJ', 'Temptation Key', array['Glenn A. Bruce'], 2012, 'Temptation Key is set in 1966 in the upper Florida Keys. It is a comic story of learning and leaving behind, which follows the exploits of a group of Conch kids as they learn about life and leave behind their childhoods. It is both funny and scary as two of the boys - 18-year-old Robbie and his best young friend 14-year-old Buddy - go on the adventure of their lives. Life in the Florida Keys in 1966 was hard, the men and women who prevailed were tough, and their kids were the product of a sparse, sea-oriented life. Temptation Key captures a time and a place as unique to the American experience as you will find. It is hilarious, exciting and satisfying, everything a good story should be.', 'https://books.google.com/books/content?id=Id9VLwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 292, 'http://play.google.com/books/reader?id=Id9VLwEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
