INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('EpDwxwEACAAJ', 'The Confession of a Battered Wife', array['W. W. Tracy'], 2019, 'RULE #1 CRIME CAN NOT BE COMMITTED AGAINST WOMEN When Jack Stacey finds himself at the scene of a homicide, he quickly identifies the profile as belonging to Michael Bittaker. Bittaker, and the local blue have been hot for each other for thirty-six years, without a single conviction. Some would say that''s an epic effort in the life of a criminal. Stacey calls upon his partner, DCI Alexis Murphy, and as soon as she crosses the cordon, the past is haunting. The body count is steadily rising, and the chief suspect was recently cremated. As the pair set out to capture a ghost, they are forced to dispose Bittaker''s ex-wife. When Sarah makes a series of chilling confessions, they discover their perp is not the monster they''ve been chasing and their failure to close a domestic violence case, has resulted in the rising of a serial killer. A chilling Australian story that weaves the tale of Domestic Violence, from a multifaceted perspective. The hard part isn''t identifying culpability, it''s allocating fair distribution of it.', 'https://books.google.com/books/content?id=EpDwxwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 531, 'http://play.google.com/books/reader?id=EpDwxwEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
