INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('ulwCvgAACAAJ', 'Dark Waters', array['Mark Peyton'], 2016, 'Dr. Steve Langley, a reclusive psychiatrist with a dark past goes out on a warm summer night in the elusive search for Pokémon when, he stumbles upon an old manor where he encounters a young lady with a troubled past and a brother with a secret to hide. When she makes him an offer he can''t refuse, his world is turned upside down as he battles to stay alive.From #1 bestselling author Mark Peyton comes this standalone mystery novel inspired by the Pokémon Go craze sweeping the world! It tells the story of what happens when one gamer''s search for augmented reality Pokémon creatures becomes a real-life cat and mouse game of murder and intrigue.', 'https://books.google.com/books/content?id=ulwCvgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 50, 'http://play.google.com/books/reader?id=ulwCvgAACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
