INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('updanAEACAAJ', 'The Man', array['Glenn A. Bruce'], 2013, 'The Man is a tense, dark non-linear roller coaster ride from thriller writer Glenn A. Bruce. The complex story of a family man whose past will certainly destroy everything he loves - and everyone he loves with it - is a time-twisted excursion into his former ways as his present unfolds at a frightening pace. His world is completely spinning out of control and he can do nothing to stop it - unless he returns to The Man he was. His Wife can''t possibly understand why their daughter is missing, or how her own dark past is the key piece in this unsettling puzzle that becomes their lives. In The End, there are really no choices but one. The question is: Who will make that final decision? Will it be The Man, his Wife - or others who cruelly hold their fate in fickle, vengeful hands.', 'https://books.google.com/books/content?id=updanAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 184, 'http://play.google.com/books/reader?id=updanAEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
