INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('XvblngEACAAJ', 'Murder Most Judgmental', array['M. J. Hatch'], 2014, 'MURDER MOST JUDGMENTAL A DETECTIVE JAKE SWANSON MURDER MYSTERY A family law judge is killed in the driveway of his upscale Newport Beach home; his wife shot through the heart in their garage. Is this a revenge killing for a ruling the judge made in court by a disgruntled party, or is the killing related to his prior life as a criminal defense lawyer? With the rich and famous of Orange County, California, any of these are possible, sending Newport Beach Homicide Detective Jake Swanson on the hunt for a killer unafraid to take down a respected judge in his own home. Complicating his investigation is an agent from a secretive government agency who keeps turning up at inopportune times-with the same agent compromising Swanson''s partner, Melissa Sanchez. Can Detective Jake Swanson keep far enough ahead of the forces interceding in the investigation, or in his hunt for a killer will Jake finally push the rich and powerful too far, losing his job, and possibly his life? Murder Most Judgmental is the second in the series of the Detective Jake Swanson murder mysteries. To meet Jake and his partner, Melissa Sanchez, look for Murder Most Blonde available through Amazon.com or retail booksellers everywhere.', 'https://books.google.com/books/content?id=XvblngEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 462, 'http://play.google.com/books/reader?id=XvblngEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
