INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('rXka0QEACAAJ', 'Cops & Robbers', array['Justin M. Kiska'], 2025, 'Spring, 1985¿ Just north of Parker City in the small town of Wakeville, a string of robberies have the residents of the quiet community on edge. Then, when two homes in one of Parker City''s wealthiest neighborhoods are broken into on the same night, PCPD Detectives Ben Winters and Tommy Mason wonder if the crime wave has spilled into their jurisdiction. There''s one chilling difference, though. This time, the intruders left a dead body behind in their wake. As Ben and Tommy delve into the investigation, what initially appears to be a robbery gone wrong soon unravels into something far more sinister. Their pursuit of the truth leads them down a path, uncovering ties to a crime spree that shook Baltimore fifty years earlier. As past and present collide, the young detectives must race to find a killer driven by a motive buried deep in the past.', 'https://books.google.com/books/content?id=rXka0QEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 'http://play.google.com/books/reader?id=rXka0QEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
