INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('0lD6vQAACAAJ', 'The Devil''s Country', array['Harry Hunsicker'], 2017, 'Former Texas Ranger Arlo Baines didn''t come to the tiny West Texas town of Piedra Springs to cause trouble. After his wife and children were murdered, Arlo just wants to be left alone. Moving from place to place seems to be the only thing that eases the pain of his family''s violent end. But a chance encounter outside a bar forces him to rescue a terrified woman and her children from mysterious attackers. When the woman turns up murdered the next day--her children missing--Arlo becomes the primary suspect in exactly the same type of crime he is trying desperately to forget. Haunted by the fate of his family, and with the police questioning the existence of the dead woman''s children, Arlo decides it''s his duty to find them. The question is, just how deep will he have to sink into the dusty secrets of Piedra Springs to save them and clear his name?', 'https://books.google.com/books/content?id=0lD6vQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 'http://play.google.com/books/reader?id=0lD6vQAACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
