INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('yI7v0AEACAAJ', 'Late Checkout', array['Alan Orloff'], 2024, 'Motel proprietor Mess Hopkins is more interested in helping others than turning a profit, so he opens the doors of the Fairfax Manor Inn to those seeking refuge from a bad situation. But when his cousin Finn shows up in trouble, his world is rocked, because Mess had thought Finn was dead, having run away six years earlier. Unfortunately, Finn was in the wrong place at the wrong time and saw the wrong thing-an incident with deadly consequences. It''s up to Mess, his girlfriend/newspaper reporter Lia Katsaros, and buddy Vell Jackson to solve the crime before some bad men achieve their goal-killing the only eyewitness. Mess''s frightened cousin Finn.', 'https://books.google.com/books/content?id=yI7v0AEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 'http://play.google.com/books/reader?id=yI7v0AEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
