INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('5uNb0AEACAAJ', 'The Trials of Marjorie Crowe', array['C.S. ROBERTSON'], 2025, 'How do you solve a murder when everyone thinks you''re guilty? Marjorie Crowe lives in Kilgoyne, Scotland. The locals put her age at somewhere between 55 and 70. They think she''s divorced or a lifelong spinster; that she used to be a librarian, a pharmacist, or a witch. They think she''s lonely, or ill, or maybe just plain rude. For the most part, they leave her be. But one day, everything changes. Local teenager Charlie McKee is found hanging in the woods, and Marjorie is the first one to see his body. When what she saw turns out to be impossible, the police have their doubts. And when another young person goes missing, the tide of suspicion turns on her. Is Marjorie the monster, or the victim? And how far will she go to fight for her name? PRAISE FOR C.S. ROBERTSON: ''A truly startling novel'' Sunday Times ''A remarkable thriller'' Sunday Express ''Ingenious'' Daily Mail ''Enthralling'' Liz Nugent ''Gut-wrenching'' The Times', 'https://books.google.com/books/content?id=5uNb0AEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 'http://play.google.com/books/reader?id=5uNb0AEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
