INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('0TT6zgEACAAJ', 'The Girl in the Gazebo', array['P . C. James'], 2022, 'The coroner report says accident. Her gut tells her homicide. Can this shrewd accountant get to the root of a tragic and mysterious death? Canadian Lakes, 1984. Miss Riddell is a strong believer in justice. So when her grieving boss calls in the forensic auditor to help investigate the accidental demise of his sixteen-year-old daughter, she quickly gets to work. But despite the authorities'' certainty that the tragedy was an unintended overdose, Miss Riddell soon suspects foul play... Tirelessly gathering information and testimonies, the detail-oriented woman''s instincts are confirmed when the girl''s supposed storyline doesn''t match the facts. And with the killer still hiding in plain sight, Miss Riddell fears they could strike again at a moment''s notice. Will Miss Riddell unmask the culprit before they return to claim more innocent lives? The Girl in the Gazebo is the page-turning sixth book in the Miss Riddell Cozy Mysteries series. If you like complex puzzles, grounded sleuths, and eye-opening reveals, then you''ll love P.C. James''s curious adventure. Buy The Girl in the Gazebo to lay this case to rest today!', 'https://books.google.com/books/content?id=0TT6zgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 'http://play.google.com/books/reader?id=0TT6zgEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
