INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('YyBKDwAAQBAJ', 'Sometimes I Lie', array['Alice Feeney'], 2018, 'Amber wakes up in a hospital. She can''t move. She can''t speak. She can''t open her eyes. Though she can hear everyone around her, no one knows because she''s in a coma. But she doesn''t remember what happened. And she has a sneaking suspicion her husband had something to do with it. Alternating between her paralyzed present, the week before her accident, and a series of childhood diaries from twenty years ago, the narratives build and collide for an ending that leaves readers speechless. This novel delves into the blurred gap between who we are and who we''d like to be.', 'https://books.google.com/books/content?id=YyBKDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 272, 'http://play.google.com/books/reader?id=YyBKDwAAQBAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
