INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('lBLiDQAAQBAJ', 'The Book of Mirrors', array['E. O. Chirovici'], 2017, 'ONE MAN''S TRUTH IS ANOTHER MAN''S LIE. When big-shot literary agent Peter Katz receives an unfinished manuscript entitled The Book of Mirrors, he is intrigued. The author, Richard Flynn is writing a memoir about his time at Princeton in the late 80s, documenting his relationship with the famous Professor Joseph Wieder. One night in 1987, Wieder was brutally murdered in his home and the case was never solved. Peter Katz is hell-bent on getting to the bottom of what happened that night twenty-five years ago and is convinced the full manuscript will reveal who committed the violent crime. But other people''s recollections are dangerous weapons to play with, and this might be one memory that is best kept buried.', 'https://books.google.com/books/content?id=lBLiDQAAQBAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 338, 'http://play.google.com/books/reader?id=lBLiDQAAQBAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
