INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('4uh30QEACAAJ', 'Cathedrals', array['Claudia Piñeiro'], 2026, 'Lia fled her home after a brutal crime decades ago, but family, and the truth, will never let you go.Thirty years ago, in an empty plot of a quiet neighbourhood, a teenage girl''s body was found quartered and burned. The investigation ended with no arrests and her family - middle class, educated, Catholic - quietly disintegrated. Three decades later, the hidden truth comes to light thanks to the father''s ongoing love for the victim. That truth will reveal the raw realities lurking behind appearances, the cruelty of those who prioritize obedience and religious fanaticism, the complicity of the fearful and the indifferent, and the loneliness and desperation of those who seek to follow their own path, ignoring the dictates of their elders.Just as she did with Elena Knows and A Little Luck , Claudia Piñeiro delves into family ties, social prejudice, and the ideologies and institutions that affect our inner worlds to deliver a brave, moving novel that strikes at the heart of these private dramas.', 'https://books.google.com/books/content?id=4uh30QEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 'http://play.google.com/books/reader?id=4uh30QEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
