INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('IhrSvQEACAAJ', 'The Turn of the Key', array['Ruth Ware'], 2019, 'IT WAS THE DREAM JOB. IT WOULD BECOME HER WORST NIGHTMARE. ''So clever and original . . . from the first gripping page to the last shocking twist'' ERIN KELLY, author of He Said/She Said ''Ruth Ware just gets better and better. The Turn of the Key is her most compelling and addictive to date; I read this in a two sitting frenzy, barely able to turn the pages fast enough'' Lisa Jewell, author of The People Upstairs When Rowan stumbles across the advert, it seems like too good an opportunity to miss: a live-in nanny position, with a very generous salary. And when she arrives at Heatherbrae House, she is smitten by the luxurious ''smart'' home fitted out with all modern conveniences by a picture-perfect family. What she doesn''t know is that she''s stepping into a nightmare - one that will end with a child dead and her in cell awaiting trial for murder. She knows she''s made mistakes. But she''s not guilty - at least not of murder. Which means someone else is... ''Will hold you captive until the brilliant ending'' SHARI LAPENA, author of Someone We Know Full of chilling menace and sinister secrets, The Turn of the Key is a gripping modern-day haunted house novel that will keep you reading through the night. Everyone loves Ruth Ware''s binge-worthy psychological thrillers: ''The queen of creepy crime'' Metro ''Eerie and tense, this left me so spooked that I slept with the light on!'' Prima ''Powerfully atmospheric, unguessably twisty...I devoured it'' Louise Candlish, bestselling author of Our House ''Dark and dramatic...part murder mystery, part family drama, altogether riveting'' A.J. Finn, author of The Woman in the Window ''Creepy, engrossing, and oh-so-hard to put down'' JP Delaney, author of The Girl Before ''One of the best thriller writers around'' Independent ''Agatha Christie meets The Girl on the Train'' The Sun ''Dark, unsettling, brilliant'' HEAT ''Deliciously dark and spooky'' Sunday Mirror', 'https://books.google.com/books/content?id=IhrSvQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 352, 'http://play.google.com/books/reader?id=IhrSvQEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
