         VALUES ('D8plAAAAMAAJ', 'Killer Weekend', array['Ridley Pearson'], 2007, 'Eight years after saving the life of a U.S. attorney general from an assassination attempt, county sheriff Walt Fleming finds himself once again protecting the high-profile politician, now a presidential hopeful, during a billionaire''s communications conference, an effort that is hampered by jurisdictional squabbles and elements from Fleming''s past. 150,000 first printing.', 'https://books.google.com/books/content?id=D8plAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 342, 'http://play.google.com/books/reader?id=D8plAAAAMAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
