INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('PzTWwAEACAAJ', 'Out', array['NATSUO. KIRINO'], 2019, 'VINTAGE JAPANESE CLASSICS - five masterpieces of Japanese fiction in gorgeous new gift editions. In the Tokyo suburbs four women work the graveyard shift at a factory. Burdened with heavy debts, alienated from husbands and children, they all secretly dream of a way out of their dead-end lives. A young mother among them finally cracks and strangles her philandering, gambling husband. She confesses her crime to her colleagues and unexpectedly, they agree to help. But then the dismembered body parts are discovered, the police start asking questions and more dangerous enemies begin to close in. OUT is a psychologically taut and unflinching foray into the darkest recesses of the human soul, an unsettling reminder that the desperate desire for freedom can make the most ordinary person do the unimaginable.', 'https://books.google.com/books/content?id=PzTWwAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 528, 'http://play.google.com/books/reader?id=PzTWwAEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
