INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('QeU8GJg_tZcC', 'Hornet''s Nest', array['Patricia Daniels Cornwell'], 1998, 'Hornet''s Nest is the first book in the Andy Brazil series, from bestselling author Patricia Cornwell. Deputy Chief Virginia West likes and respects her boss, Hammer, but with an increasing number of visiting businessmen being murdered in her city by a maniac with a penchant for painting his victims bright orange, she finds it hard to accept Hammer''s edict that a rookie reporter should ride on patrol with her to better relations with their citizens. Her worst fears are confirmed when the reporter, Brazil, presses the button to activate the boot-release rather than the siren on their first outing. He''s not the only blight on her life right now: her cat''s angsty, her hormones are misbehaving, her opposite number in the uniformed division is behaving like a jackass, the radio despatcher is determined to trip her up, the D.A. is in the middle of a hot battle with the trial schedule. And orange coloured corpses keep turning up on her patch. A realistic and entertaining thriller which throws an ironic light on how to police a city.', 'https://books.google.com/books/content?id=QeU8GJg_tZcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 456, 'http://play.google.com/books/reader?id=QeU8GJg_tZcC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
