INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('4avovQEACAAJ', 'The Family Upstairs', array['Lisa Jewell'], 2019, 'FROM THE #1 BESTSELLING AUTHOR OF THEN SHE WAS GONE In a large house in London''s fashionable Chelsea, a baby is awake in her cot. Well-fed and cared for, she is happily waiting for someone to pick her up. In the kitchen lie three decomposing corpses. Close to them is a hastily scrawled note. They''ve been dead for several days. Who has been looking after the baby? And where did they go? Two entangled families. A house with the darkest of secrets. A compulsive new thriller from Lisa Jewell.', 'https://books.google.com/books/content?id=4avovQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 464, 'http://play.google.com/books/reader?id=4avovQEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
