INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('p59eEQAAQBAJ', 'Dark Is When the Devil Comes', array['Daisy Pearce'], 2026, 'Unrelentingly scary and thrilling, Dark Is When the Devil Comes is an ambitious and chilling novel from acclaimed horror author Daisy Pearce. The woods are known as the place to avoid. What goes in, doesn’t come out. Hazel has been gone from her small hometown of Kawdarn in the English countryside for years. Now returned in the wake of a traumatic divorce and crumbling personal life, her simple plans are to lay low at her parents’ vacated house, reconnect with her prickly sister Cathy, and slowly get back on her feet. Cathy is surprised when Hazel doesn’t show. Their relationship strained from a fallout half a decade ago, she didn’t expect them to get back into a sisterly rhythm...though she hadn’t counted on Hazel bailing, either. But something isn’t adding up. Other people in town whisper of a threat that can’t be shaken. The woods are known for being restless. And Cathy knows the old saying. If you go looking for trouble, you just might find it.', 'https://books.google.com/books/content?id=p59eEQAAQBAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 'http://play.google.com/books/reader?id=p59eEQAAQBAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
