INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('ZdGhDAEACAAJ', 'The Nowhere Man', array['Gregg Hurwitz'], 2017, 'Han gikk tidligere under navnet Orphan X. Som liten gutt ble Evan Smoak tatt ut av barnehjemmet og oppdratt og trent opp som en del av et hemmelig statlig initiativ, så langt under jorda at nesten ingen vet at det finnes. Men han valgte å bryte opplæringen, og heller bruke sine formidable evner til å hjelpe de som ikke kan beskytte seg selv. Men en dag er det slutt på flaksen for Evan. Etter å ha blitt overfalt og neddopet, våkner han opp i et låst rom uten en anelse om hvor befinner seg eller hvem som har fanget han. Mens han forsøker å finne ut av hva som har skjedd, hører han et desperat rop om hjelp. Men tiden er i ferd med å løpe ut. Han må redde seg selv for å klare å beskytte de som er avhengig av han. "The nowhere man" er en actionfylt thriller. Omtalen er utarbeidet av BS.', 'https://books.google.com/books/content?id=ZdGhDAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 'http://play.google.com/books/reader?id=ZdGhDAEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
