INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('Xp9srgEACAAJ', 'The North Water', array['Ian McGuire'], 2016, 'A 19th-century whaling ship sets sail for the Arctic with a killer aboard in this dark, sharp and highly original tale that grips like a thriller. Behold the man: stinking, drunk, brutal and bloodthirsty, Henry Drax is a harpooner on the Volunteer, a Yorkshire whaling ship bound for the hunting waters of the Arctic Circle. Also aboard is Patrick Sumner, an ex-army surgeon with a shattered reputation, no money and no better option than to embark as ship''s medic on this ill-fated voyage. In India during the Siege of Delhi, Sumner thought he had experienced the depths to which a man can stoop and imagined he''d find respite on the Volunteer, but now, trapped in the wooden belly of the ship with Drax, he encounters pure evil and is forced to act. As the true purposes of the expedition become clear, the confrontation between the two men plays out in the freezing darkness of an Arctic winter.', 'https://books.google.com/books/content?id=Xp9srgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 336, 'http://play.google.com/books/reader?id=Xp9srgEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
