INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('wcfHPQzq6BEC', 'The Tesla Legacy', array['Robert G. Barrett'], 2007, '"Forget the bloody Da Vinici code, Mick. We''ve got to crack the Tesla Legacy. If we don''t we''re both dead." Despite the Pentagon, it had to be found... ''Forget the bloody Da Vinci Code, Mick. We''ve got to crack the tesla Legacy. If we don''t, we''re both dead.''Newcastle electrician Mick Vincent had almost everything in life he wanted. Jesse Osbourne, the Stockton bookshop owner he loved. A big house at Bar Beach. Not to mention a 1936 Buick Roadmaster ... in fact, the only thing Mick was missing was a pressure plate for his cherished car. through a strange old lady, Mick finds his pressure plate. He also finds a diary belonging to Nikola tesla, the electronics genius reputed to be smarter than Einstein. But just what did tesla build in outback New South Wales in 1925?the Pentagon knows, and the race is on to be the first to find the tesla Legacy. Mick and Jesse''s only clues are a lost mountain of copper ore and an old racehorse called tears of Fire.Robert G. Barrett''s novel the tesla Legacy, set in Newcastle, Muswellbrook, Scone and mysterious Burning Mountain in New South Wales, is an action-packed, pace-driven thriller woven with intrigue and a delightful touch of humour and romance, and an ending guaranteed to send chills down your spine. Proving once again why author Robert G. Barrett is, according to the Australian newspaper, the king of popular fiction.''Do not read this book in public unless you are comfortable laughing in front of strangers'' Sydney Morning Herald''a cracker of a read ... a good touch of the smarts and lashings of heartfelt humour'' West Australian''a flat-out terrific yarn'' the Australian', 'https://books.google.com/books/content?id=wcfHPQzq6BEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 'http://play.google.com/books/reader?id=wcfHPQzq6BEC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
