INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('Y12-OQ5BDjcC', 'Northern Lights', array['Nora Roberts'], 2004, 'Lunacy, Alaska - population 506 - is Nate Burke''s last chance. As a Baltimore cop, he had watched his partner die - and the guilt still haunts him. Maybe serving as Chief of Police in this tiny, remote town, where darkness falls by mid-afternoon and temperatures fall to below zero, will bring some kind of solace. It isn''t as if he has anywhere else to go. Aside from sorting out a run-in between a couple of motor vehicles and a moose and pulling apart two brothers fighting overJohn Wayne''s best movie Nate''s first weeks on the job are relatively quiet. But as he wonders whether this was all a big mistake, an unexpected kiss from feisty bush pilot Meg Galloway under the brilliant Northern Lights of the Alaska sky lifts his spirit - and convinces him to stay just a little longer. Born and raised in Lunacy, Meg has learned to be independent. But there''s something about Nate''s sad eyes that gets under her skin, and warms her frozen heart. However, when two climbers find a corpse on the mountain, Nate discovers that Lunacy isn''t quite the sleepy little backwater he imagined.', 'https://books.google.com/books/content?id=Y12-OQ5BDjcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 580, 'http://play.google.com/books/reader?id=Y12-OQ5BDjcC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
