INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('03WquAAACAAJ', 'Jane Eyre', array['Charlotte Brontë'], 2010, 'Bronte''s infamous Gothic novel tells the story of orphan Jane, a child of unfortunate circumstances. Raised and treated badly by her aunt and cousins and eventually sent away to a cruel boarding school, it is not until Jane becomes a governess at Thornfield that she finds happiness. Meek, measured, but determined, Jane soon falls in love with her brooding and stormy master, Mr Rochester, but it is not long before strange and unnerving events occur in the house and Jane is forced to leave Thornfield to pursue her future.', 'https://books.google.com/books/content?id=03WquAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 462, 'http://play.google.com/books/reader?id=03WquAAACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
