INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('TmDhCwAAQBAJ', 'The Girl from Summer Hill', array['Jude Deveraux'], 2016, 'The first novel of New York Times bestselling author Jude Deveraux''s breathtaking series set in Summer Hill, a small town where love takes centre stage against the backdrop of Jane Austen''s Pride and Prejudice. Enter Elizabeth Bennet. Chef Casey Reddick has had it up to here with men. Arriving in the charming town of Summer Hill, Virginia, peace and quiet on the picturesque Tattwell plantation is just what she needs. But the tranquillity is broken one morning when she sees a gorgeous naked man on her porch. Enter Mr. Darcy. What Tate Landers, Hollywood heartthrob and owner of Tattwell, doesn''t need on a bittersweet trip to his ancestral home is a woman spying on him. His anger, which looks so good on the screen, makes a bad first impression on Casey - and she lets him know it', 'https://books.google.com/books/content?id=TmDhCwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 385, 'http://play.google.com/books/reader?id=TmDhCwAAQBAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
