INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('-a-YQwAACAAJ', 'Spirit Bound', array['Richelle Mead'], 2010, 'The international number 1 bestselling Vampire Academy series by Richelle Mead is now a major motion picture. Read it before it hits cinemas in 2014! SALVATION HAS ITS PRICE . . . Fall in love with Rose and Dimitri all over again in Spirit Bound, the anticipated fifth novel in Richelle Mead''s enthralling Vampire Academy series. After a long and heartbreaking journey to Siberia, Dimitri''s birthplace, Rose Hathaway has finally returned to St. Vladimir''s - and to her best friend, Lissa Dragomir. It''s graduation, and the girls can''t wait for their real lives outside the Academy''s cold iron gates to finally begin. But even with the intrigue and excitement of court life looming, Rose''s heart still aches for Dimitri. He''s out there, somewhere. She failed to kill him when she had the chance, and now her worst fears are about to come true. Dimitri has tasted her blood, and she knows in her heart that he is hunting her. And if Rose won''t join him, he won''t rest until he has silenced her . . . forever. But Rose can''t forget what she learned on her journey - whispers of a magic too impossible and terrifying to comprehend. A magic inextricably tied to Lissa that could hold the answer to all of Rose''s prayers, but not without devastating consequences. Now Rose will have to decide what - and who - matters most to her. And in the end, is true love really worth the price? penguinteenaustralia.com', 'https://books.google.com/books/content?id=-a-YQwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 489, 'http://play.google.com/books/reader?id=-a-YQwAACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
