INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('zVgzqWOh5QUC', 'The Klone and I', array['Danielle Steel'], 1998, 'After thirteen years of marriage and two kids. Stephanie was devastated when her husband left her for a younger woman. Suddenly she was alone. Then a spur-of-the-moment trip to Paris changed everything. Peter Baker was a handsome high-tech entrepreneur also visiting the city. Stephanie was certain it couldn''t possibly work. But much to her amazement, he contacted her when they returned to New York. And Stephanie embarked on a bizarre and hilarious adventure beyond her wildest dreams. Shy, serious Peter, chairman of a bionic enterprise, was supposed to be away on business. Instead, he''s standing at her door, wearing satin and rhinestones. Naturally, Stephanie thinks it''s a joke -- until the truth suddenly dawns: this isn''t Peter playing a role. This is his double! Calling himself Paul Klone, this wild, uninhibited creature isn''t even remotely like Peter except for his identically sexy good looks. This uproarious novel explores the outrageous love triangle that develops between Stephanie, Peter...and The Klone. In a wickedly funny, right-on-target look at finding the per-feet mate in an imperfect world, bestselling novelist Danielle Steel reveals insights into the human heart that have made her novels #1 bestsellers around the world.', 'https://books.google.com/books/content?id=zVgzqWOh5QUC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 244, 'http://play.google.com/books/reader?id=zVgzqWOh5QUC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
