INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('zsLVEQAAQBAJ', 'Pride and Prejudice and Zombies', array['Jane Austen','Seth Grahame-Smith'], 2009, 'The New York Times Best Seller is now a major motion picture starring Lily James and Sam Riley, with Matt Smith, Charles Dance, and Lena Headey. This movie tie-in edition features 16 pages of color stills from the film, a reading group discussion guide, and other bonus materials. “It is a truth universally acknowledged that a zombie in possession of brains must be in want of more brains.” So begins Pride and Prejudice and Zombies, a bold reimagining of Jane Austen’s classic novel. As our story opens, a mysterious plague has fallen upon the quiet English village of Meryton—and the dead are returning to life. Feisty heroine Elizabeth Bennet is determined to wipe out the zombie menace, but she’s soon distracted by the haughty and arrogant Mr. Darcy. What ensues is a delightful comedy of manners with plenty of civilized sparring between the two young lovers—and even more violent sparring on the bloodsoaked battlefield. Complete with romance, heartbreak, swordfights, cannibalism, and thousands of rotting corpses, Pride and Prejudice and Zombies is an audacious retelling of English literature’s most enduring novel.', 'https://books.google.com/books/content?id=zsLVEQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 373, 'http://play.google.com/books/reader?id=zsLVEQAAQBAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
