         VALUES ('A6IwzQEACAAJ', 'Ethan Frome', array['Edith Wharton'], 2019, 'Reproduction print of the classic novel: Ethan Frome by Edith WhartonLARGE PRINT Edition Fonts used in this series have been selected in order to ensure optional reading for those with visual impairments. Font size is greater than or equal to 16pt, Sans Serif This print is part of the KoF Classic Reprint Series. In the KoF Classic Reprint Series, careful attention is taken to digitally remaster these great works of literature using the latest digital techniques and special processing. We hope you enjoy the result.', 'https://books.google.com/books/content?id=A6IwzQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 190, 'http://play.google.com/books/reader?id=A6IwzQEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
