INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('eHLRAAAACAAJ', 'Spiral', array['Sakura Mizuki','Koji Suzuki'], 2004, 'The popular novel The Ring has seen the lion''s share of publicity, but that''s not where the story ends. In this adaptation of Suzuki''s next novel Spiral (Rasen in Japanese), the legend of Sadako''s evil takes a scientific turn, as Ryuji Takayama''s old college friend, Mitsuo Ando, must decipher a mysterious code while investigating this strange virus that kills people after watching a video tape. Disbelief gives way to fear. Logic bends to survival. And human evolution changes drastically. What Sadako plans is not simply horror, but something much, much deeper.', 'https://books.google.com/books/content?id=eHLRAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 'http://play.google.com/books/reader?id=eHLRAAAACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
