INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('8khaAAAAMAAJ', 'Bitten', array['Kelley Armstrong'], 2001, '"Young, beautiful, and successful, Elena Michaels seems to have it all. Her happy, organized life follows a predictable pattern: filing stories for her job as a journalist, working out at the gym, living with her architect boyfriend, and lunching with her girlfriends from the office. And once a week, in the dead of night, she streaks through a downtown ravine, naked and furred, tearing at the throats of her animal prey." "Elena Michaels is a werewolf." "The man who made her one has been left behind, but his dark legacy has not. And though Elena struggles to maintain the normal life she''s worked so hard to create, she cannot resist the call of the elite pack of werewolves from her past. Her feral instincts will lead her back to them and into a desperate war for survival that will test her own understanding of who, and what, she is."--BOOK JACKET.Title Summary field provided by Blackwell North America, Inc. All Rights Reserved', 'https://books.google.com/books/content?id=8khaAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 358, 'http://play.google.com/books/reader?id=8khaAAAAMAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
