INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('vPS65zz97EAC', 'Featherless Chickens, Laughing Women, and Serious Stories', array['Jeannie B. Thomas'], 1997, 'Interested in preserving her family folklore, Jeannie B. Thomas recorded detailed oral histories from her mother and two grandmothers. While analyzing the tapes of these sessions, she notices the inappropriate laughter often accompanied the retelling of painful stories. In this book, Thomas combines these personal narratives with original scholarship drawing on the work of Mikhail Bakhtin and Julia Kristeva to uncover meaning behind the startling presence of unconventional laughter in women''s histories.', 'https://books.google.com/books/content?id=vPS65zz97EAC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 246, 'http://play.google.com/books/reader?id=vPS65zz97EAC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
