INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('n565nAEACAAJ', 'The Shrinking Man', array['Richard Matheson'], 2014, 'While on a boating holiday, Scott Carey is exposed to a cloud of radioactive spray. A few weeks later, following a series of medical examinations, he can no longer deny the extraordinary truth. Not only is he losing weight, he is also shorter than he was. Scott Carey has begun to shrink. Richard Matheson''s novel follows through its premise with remorseless logic, with Carey first attempting to continue some kind of normal life and later having left human contact behind, having to survive in a world where insects and spiders are giant adversaries. And even that is only a stage on his journey into the unknown.', 'https://books.google.com/books/content?id=n565nAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 208, 'http://play.google.com/books/reader?id=n565nAEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
