INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('Sfv4zgEACAAJ', 'An Offer from a Gentleman LP', array['Julia Quinn'], 2022, 'A New York Times Bestseller From #1 New York Times bestselling author Julia Quinn comes the story of Benedict Bridgerton, in the third of her beloved Regency-set novels featuring the charming, powerful Bridgerton family, now a series created by Shondaland for Netflix. BENEDICT''S STORY Sophie Beckett never dreamed she''d be able to sneak into Lady Bridgerton''s famed masquerade ball--or that "Prince Charming" would be waiting there for her! Though the daughter of an earl, Sophie has been relegated to the role of servant by her disdainful stepmother. But now, spinning in the strong arms of the debonair and devastatingly handsome Benedict Bridgerton, she feels like royalty. Alas, she knows all enchantments must end when the clock strikes midnight. Ever since that magical night, a radiant vision in silver has blinded Benedict to the attractions of any other--except, perhaps, this alluring and oddly familiar beauty dressed in housemaid''s garb whom he feels compelled to rescue from a most disagreeable situation. He has sworn to find and wed his mystery miss, but this breathtaking maid makes him weak with wanting her. Yet, if he offers her his heart, will Benedict sacrifice his only chance for a fairy-tale love?', 'https://books.google.com/books/content?id=Sfv4zgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 512, 'http://play.google.com/books/reader?id=Sfv4zgEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
