INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('dgsezgEACAAJ', 'Warriors of God', array['Andrzej Sapkowski'], 2021, 'The second volume of the Hussite Trilogy by the New York Times bestselling author of The Witcher takes Reynevan - scoundrel, magician, possibly a fool - into the depths of war as he attempts to navigate the religious fervors of the fifteenth century. When the Hussite leaders entrust Reynevan with a dangerous secret mission, he is forced to come out of hiding in Bohmeia and depart for Silesia. At the same time, he strives to avenge the death of his brother and discover the whereabouts of his beloved. Once again pursued by multiple enemies, he must contend with danger on every front. Full of gripping action replete with twists and mysteries, seasoned with magic and Sapkowski''s ever-present wit, fans of the Witcher will appreciate this rich historical epic set during the Hussite Wars. Praise for the The Tower of Fools, book one of the Hussite Trilogy: "This is historical fantasy done right." --Publishers Weekly (starred review) "A fantastic novel that any fan of The Witcher will instantly appreciate." --The Gamer "A ripping yarn delivered with world-weary wit, bursting at the seams with sex, death, magic and madness." --Joe Abercrombie "Sapkowski''s energetic and satirical prose as well as the unconventional setting makes this a highly enjoyable historical fantasy." --Booklist Also by Andrzej Sapkowski: The Hussite Trilogy The Tower of Fools Warriors of God Witcher collections The Last Wish Sword of Destiny Witcher novels Blood of Elves The Time of Contempt Baptism of Fire The Tower of Swallows Lady of the Lake Season of Storms The Malady and Other Stories: An Andrzej Sapkowski Sampler (e-only) Translated by David French', 'https://books.google.com/books/content?id=dgsezgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 464, 'http://play.google.com/books/reader?id=dgsezgEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
