INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('2p9WzwEACAAJ', 'The Paris Daughter', array['Kristin Harmel'], 2023, '''An unmissable reading treat'' Lancashire Evening Post ''Beautifully written and emotionally charged . . . impossible to put down'' HAZEL GAYNOR A heartwrenching and evocative wartime novel, perfect for fans of Santa Montefiore, Rachel Hore and Lucinda Riley. Two mothers. Two daughters. Two families torn apart forever. Paris, 1939. Elise and Juliette are certain nothing can come between them. So, when war breaks out and Elise is forced to flee, she entrusts Juliette with her daughter, playmate to Juliette''s own little girl. More than a year later, with the war finally ending, Elise returns to reunite with her daughter, only to find her friend''s bookstore reduced to rubble - and Juliette nowhere to be found. What happened to Mathilde in those last terrible moments? Juliette has seemingly vanished without a trace, taking all the answers with her. Elise''s desperate search leads her to New York - and to Juliette - one final, fateful time. The Paris Daughter is a story about mothers and daughters, the way loss transforms us, and the roads we find to beginning anew in the face of impossible odds. PRAISE FOR KRISTIN HARMEL: ''Kristin Harmel is firmly in the top echelon of WW2 storytellers'' HEATHER MORRIS ''A master storyteller'' SANTA MONTEFIORE', 'https://books.google.com/books/content?id=2p9WzwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 'http://play.google.com/books/reader?id=2p9WzwEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
