INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('dEBkAQAACAAJ', 'The Lady''s Guard', array['Christi Caldwell'], 2017, 'At the notorious Hell and Sin Club nestled in London''s dark streets, Niall Marksman relishes taking the fortunes of the very same society that once disregarded his existence. It''s only when Lady Diana Verney appears at the gaming club looking for help that Niall knows that the devil has finally come to collect-- by forcing him to protect the duke''s pampered daughter. Disdained by the peerage and ignored by her father, Diana knows that someone wants to harm her. Now her life and safety are in the hands of the most dangerous man in London. But a man raised on the city;s mercenary streets is adept at stealing anything he wishes-- including a lady''s reputation and her heart.', 'https://books.google.com/books/content?id=dEBkAQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 'http://play.google.com/books/reader?id=dEBkAQAACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
