         VALUES ('Xrz6AorNQMMC', 'Something Red', array['Douglas Nicholas'], 2012, 'During the 13th century, in northwest England, in one of the coldest winters, a middle-aged Irishwoman and her little troupe are trying to drive their three wagons across the Pennines before a heavy snow. They soon find that something terrible prowls the woods.', 'https://books.google.com/books/content?id=Xrz6AorNQMMC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 325, 'http://play.google.com/books/reader?id=Xrz6AorNQMMC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
