INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('YponzgEACAAJ', 'The Postmistress of Paris', array['Meg Waite Clayton'], 2021, 'The New York Times bestselling author of The Last Train to London revisits the dark early days of the German occupation in France in this haunting novel--a love story and a tale of high-stakes danger and incomparable courage--about a young American heiress who helps artists hunted by the Nazis escape from war-torn Europe. Wealthy, beautiful Naneé was born with a spirit of adventure that transcends her Midwestern roots. For her, learning to fly is freedom. When German tanks roll across the border and into Paris, this woman with an adorable dog and a generous heart joins the resistance. Known as the Postmistress because she delivers information to those in hiding, Naneé uses her charms and skill to house the hunted and deliver them to safety. Inspired by the real life Chicago heiress Mary Jayne Gold, who worked with American journalist Varian Fry to smuggle artists and intellectuals out of France, Meg Waite Clayton has fashioned a sweeping tale of romance and danger, set in a world aflame with personal and political passion. The Postmistress of Paris is the haunting story of an indomitable woman whose strength, bravery, and love is a beacon of hope in a time of terror.', 'https://books.google.com/books/content?id=YponzgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 400, 'http://play.google.com/books/reader?id=YponzgEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
