           ON CONFLICT DO NOTHING;
INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('jlcCzgEACAAJ', 'The Warsaw Orphan', array['Kelly Rimmer'], 2021, '"Kelly Rimmer''s heart-stopping rendering of the war in Nazi-occupied Poland will captivate readers page by page."--Lisa Wingate, #1 New York Times bestselling author of Before We Were Yours "A surefire hit [and] a heartbreaking and hopeful story of family, duty, love, salvation, and resistance. The Warsaw Orphan [is] a thoughtful, beautiful novel." -- Kristin Harmel, New York Times bestselling author of The Book of Lost Names Inspired by the real-life heroine who saved thousands of Jewish children during WWII, The Warsaw Orphan is Kelly Rimmer''s most anticipated novel since her bestselling sensation, The Things We Cannot Say. In the spring of 1942, young Elzbieta Rabinek is aware of the swiftly growing discord just beyond the courtyard of her comfortable Warsaw home. She has no fondness for the Germans who patrol her streets and impose their curfews, but has never given much thought to what goes on behind the walls that contain her Jewish neighbors. She knows all too well about German brutality--and that it''s the reason she must conceal her true identity. But in befriending Sara, a nurse who shares her apartment floor, Elzbieta makes a discovery that propels her into a dangerous world of deception and heroism. Using Sara''s credentials to smuggle children out of the ghetto brings Elzbieta face-to-face with the reality of the war behind its walls, and to the plight of the Gorka family, who must make the impossible decision to give up their newborn daughter or watch her starve. For Roman Gorka, this final injustice stirs him to rebellion with a zeal not even his newfound love for Elzbieta can suppress. But his recklessness brings unwanted attention to Sara''s cause, unwittingly putting Elzbieta and her family in harm''s way until one violent act threatens to destroy their chance at freedom forever. From Nazi occupation to the threat of a communist regime, The Warsaw Orphan is the unforgettable story of Elzbieta and Roman''s perilous attempt to reclaim the love and life they once knew. "Intensely moving...Bravo, Kelly Rimmer! I''m going to be recommending this book to everyone I know." --Karen Robards, New York Times bestselling author of The Black Swan of Paris', 'https://books.google.com/books/content?id=jlcCzgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 416, 'http://play.google.com/books/reader?id=jlcCzgEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
