INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('5ZAl0AEACAAJ', 'The Story Spinner', array['Barbara Erskine'], 2024, 'From the Sunday Times bestselling author of Lady of Hay comes this stunning new novel... Barbara Erskine returns with a thrilling new novel in 2024... The legends of Wales have been lost to the pages of time... Silures, 384 AD Elen is a princess promised to the emperor of Rome. He had come to Wales to find a bride, or that''s what legend tells. Camp Meadow, 2024 Cadi is a writer who has discovered Elen''s lost story. As she puts pen to paper, Cadi uncovers her cottage neighbours an ancient meadow. She is convinced she can hear soldiers marching - the echoes of time lingering on... Opening the gate to the meadow behind her house, the story is about to begin...', 'https://books.google.com/books/content?id=5ZAl0AEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 'http://play.google.com/books/reader?id=5ZAl0AEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
