INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('BRpZDwAAQBAJ', 'We Were Liars', array['E. Lockhart'], 2018, '#1 NEW YORK TIMES BESTSELLER • NOW STREAMING ON PRIME VIDEO • LOOK FOR THE LATEST NOVEL IN THE WE WERE LIARS UNIVERSE, WE FELL APART! The modern, sophisticated suspense novel that became a runaway smash hit on TikTok and introduced the world to a family hiding a jaw-dropping secret. "Thrilling, beautiful, and blisteringly smart, We Were Liars is utterly unforgettable." —John Green, #1 New York Times bestselling author of The Fault in Our Stars A beautiful and distinguished family. A private island. A brilliant, damaged girl; a passionate, political boy. A group of four friends—the Liars—whose friendship turns destructive. A revolution. An accident. A secret. Lies upon lies. True love. The truth. Read it. And if anyone asks you how it ends, just LIE. Don’t miss any of the We Were Liars novels WE WERE LIARS • FAMILY OF LIARS • WE FELL APART', 'https://books.google.com/books/content?id=BRpZDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 322, 'http://play.google.com/books/reader?id=BRpZDwAAQBAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
