INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('ybFj4ftiJVoC', 'I Am the Cheese', array['Robert Cormier'], 2013, 'Before there was Lois Lowry’s The Giver or M. T. Anderson’s Feed, there was Robert Cormier’s I Am the Cheese, a subversive classic that broke new ground for YA literature. A boy’s search for his father becomes a desperate journey to unlock a secret past. But the past must not be remembered if the boy is to survive. As he searches for the truth that hovers at the edge of his mind, the boy—and readers—arrive at a shattering conclusion. “An absorbing, even brilliant job. The book is assembled in mosaic fashion: a tiny chip here, a chip there. . . . Everything is related to something else; everything builds and builds to a fearsome climax. . . . [Cormier] has the knack of making horror out of the ordinary, as the masters of suspense know how to do.”—The New York Times Book Review “A horrifying tale of government corruption, espionage, and counter espionage told by an innocent young victim. . . . The buildup of suspense is terrific.”—School Library Journal, starred review An ALA Notable Children’s Book A School Library Journal Best Book of the Year A Horn Book Fanfare A Library of Congress Children’s Book of the Year A Colorado Blue Spruce Young Adult Book Award Nominee', 'https://books.google.com/books/content?id=ybFj4ftiJVoC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 113, 'http://play.google.com/books/reader?id=ybFj4ftiJVoC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
