INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('A39XBAAAQBAJ', 'Little Women', array['Louisa May Alcott'], 2014, 'The four March sisters—Meg, Jo, Beth, and Amy—face good times and bad while growing up in a small New England town. Their father is away, serving as a chaplain for the Union in the Civil War, and the family has fallen on hard times financially. Yet their wise and patient mother, Marmee, guides them through every twist and turn. The girls play games, make friends, have adventures, learn from disappointments, fall in love, and strive to follow their dreams as they grow into young women. This unabridged version of Louisa Mae Alcott''s well-loved American novel is taken from the 1880 copyright edition, which features original illustrations by Frank T. Merrill.', 'https://books.google.com/books/content?id=A39XBAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 753, 'http://play.google.com/books/reader?id=A39XBAAAQBAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
