INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('WN5tEAAAQBAJ', 'Stranger Things: Rebel Robin', array['A. R. Capetta'], 2022, 'Discover the backstory of new Stranger Things fan favorite Robin--the perfect read for anyone looking forward to devouring the fourth season on Netflix—now available as a paperback! High school is a monster, and it''s eating everyone Robin knows. It''s the beginning of sophomore year, and Robin''s Odd Squad friends couple up, won''t stop talking about college and their future careers, and are obsessed with trying to act "normal." Robin knows that game well--she''s been pretending for years, hoping nobody would notice the sarcastic polyglot French horn player with a bad perm in the back of the room. But there''s one aspect of her identity that she knows for sure doesn''t fit in with her image--Robin likes girls. How is she supposed to be her true self in teeny-tiny Hawkins, Indiana? Robin is convinced the only way she can experience real life is by fleeing to Europe for the summer--aka Operation Croissant. But she has no money, no permission, and no one to share the adventure with--and it will take a heck of a lot more than that to escape Hawkins in one piece. Sprinkled with references to your favorite Stranger Things characters, this prequel chronicles one girl''s realization that the only person she really needs to be accepted by is herself.', 'https://books.google.com/books/content?id=WN5tEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 369, 'http://play.google.com/books/reader?id=WN5tEAAAQBAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
