INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('g9sDD687x50C', 'Brisingr', array['Christopher Paolini'], 2008, 'Don’t miss the eagerly anticipated epic new fantasy from Christopher Paolini—Murtagh! The Empire is at war and the stakes have never been higher in Book Three of the Inheritance Cycle, perfect for fans of Lord of the Rings! This New York Times bestselling series has sold over 40 million copies and is an international fantasy sensation. "Christopher Paolini is a true rarity." —The Washington Post Oaths sworn . . . loyalties tested . . . forces collide... Eragon is the greatest hope to rid the land of tyranny. Can this once simple farm boy unite the rebel forces and defeat the king? Following the colossal battle against the Empire''s warriors, Eragon and his dragon, Saphira, have narrowly escaped with their lives. Still, there is more adventure at hand for the Rider and his dragon, as Eragon finds himself bound by a tangle of promises he may not be able to keep. When unrest claims the rebels and danger strikes from every corner, Eragon must make choices-choices that will take him across the Empire and beyond, choices that may lead to unimagined sacrifice.', 'https://books.google.com/books/content?id=g9sDD687x50C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 802, 'http://play.google.com/books/reader?id=g9sDD687x50C&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
