INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('5NEWm6AvTl0C', 'The Vampire Diaries: The Awakening', array['L. J. Smith'], 2010, 'The #1 New York Times bestselling series that inspired the hit TV show The Vampire Diaries! A deadly love triangle. Elena Gilbert is a high school golden girl, used to getting what she wants. And who she wants. But when the boy she’s set her sights on—the handsome and haunted Stefan—isn’t interested, she’s confused. She could never know the real reason Stefan is struggling to resist her: Stefan is a vampire, and Elena’s in danger just by being around him. What’s more, Stefan’s dark, dangerous vampire brother Damon has just arrived in town. And wherever Damon goes, trouble always follows. Perfect for fans of Midnight Sun, The Beautiful, and Crave, this first book in the New York Times bestselling Vampire Diaries series by L. J. Smith will introduce new readers to the heart-stopping suspense, fierce romances, and jaw-dropping surprises that captured millions of fans and inspired the hit TV show. ?Perfect for Halloween Reading Ideal for fans of the supernatural For teens who love dark and scary stories', 'https://books.google.com/books/content?id=5NEWm6AvTl0C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 276, 'http://play.google.com/books/reader?id=5NEWm6AvTl0C&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
