         VALUES ('fpV0DVDxLqkC', 'Eclipse', array['Stephenie Meyer'], 2007, 'This special edition of the #1 "New York Times" bestseller includes the first chapter of "Breaking Dawn," the highly anticipated final book in the Twilight Saga, a limited-edition, full-color print, and two exclusive "Eclipse"-inspired t-shirt transfers. Consumable.', 'https://books.google.com/books/content?id=fpV0DVDxLqkC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 678, 'http://play.google.com/books/reader?id=fpV0DVDxLqkC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
