INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('pFkYCwAAQBAJ', 'Little Women', array['Alcott, Louisa M.'], 2025, 'Little Women was an immediate commercial and critical success, and readers demanded to know more about the characters. Alcott quickly completed a second volume (entitled Good Wives in the United Kingdom, although this name derived from the publisher and not from Alcott). It was also successful. The two volumes were issued in 1880 in a single work entitled Little Women. Alcott also wrote two sequels to her popular work, both of which also featured the March sisters: Little Men (1871) and Jo''s Boys (1886). AlthoughLittle Women was a novel for girls, it differed notably from the current writings for children, especially girls. The novel addressed three major themes: "domesticity, work, and true love, all of them interdependent and each necessary to the achievement of its heroine''s individual identity." Little Women "has been read as a romance or as a quest, or both. It has been read as a family drama that validates virtue over wealth", but also "as a means of escaping that life by women who knew its gender constraints only too well". According to Sarah Elbert, Alcott created a new form of literature, one that took elements from Romantic children''s fiction and combined it with others from sentimental novels, resulting in a totally new format. Elbert argued that within Little Women can be found the first vision of the "All-American girl" and that her multiple aspects are embodied in the differing March sisters.', 'https://books.google.com/books/content?id=pFkYCwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 873, 'http://play.google.com/books/reader?id=pFkYCwAAQBAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
