           SELECT 'pFkYCwAAQBAJ', categoryId FROM category WHERE categoryName = 'Young Adult Fiction'
           ON CONFLICT DO NOTHING;
INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('8u5lDAAAQBAJ', 'Sense and Sensibility', array['Jane Austen'], 2016, 'Semakin luas kulihat dunia, semakin aku yakin tak ada pria yang bisa sungguh-sungguh kucintai. Elinor dan Marianne Dashwood adalah dua saudari dengan watak dan kepribadian bertolak belakang. Elinor sang kakak mengutamakan akal sehat, sementara Marianne mementingkan perasaan. Namun keduanya sama-sama ingin menemukan cinta sejati dan menikah untuk membahagiakan ibu mereka yang telah menjanda. Ketika Marianne jatuh cinta setengah mati pada seorang pemuda bernama Willoughby, dia mengabaikan nasihat Elinor untuk berhati-hati. Dan ketika Marianne patah hati, Elinor menyembunyikan kegagalan cintanya sendiri sembari menghibur sang adik. Di masa di mana banyak orang lebih mementingkan status dan harta daripada cinta sejati, dapatkah Elinor dan Marianne menikahi pria idaman mereka? Terkadang cinta berada lebih dekat daripada yang dibayangkan, seandainya saja kita mau membuka mata. Sense and Sensibility adalah novel pertama Jane Austen, dirilis pada tahun 1811. Hingga kini, novel ini telah beberapa kali diadaptasi ke film layar lebar dan serial televisi. Salah satunya rilis pada tahun 1995, menampilkan Emma Thompson, Kate Winslet, Hugh Grant, dan Alan Rickman. [Mizan Publishing, Novel, Romance, Roman, Drama, Sastra, Klasik, Terjemahan, Indonesia]', 'https://books.google.com/books/content?id=8u5lDAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 465, 'http://play.google.com/books/reader?id=8u5lDAAAQBAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
