INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('N0Cw-UWd7mEC', 'American Born Chinese', array['Gene Luen Yang'], 2006, 'A tour-de-force by rising indy comics star Gene Yang, American Born Chinese tells the story of three apparently unrelated characters: Jin Wang, who moves to a new neighborhood with his family only to discover that he''s the only Chinese-American student at his new school; the powerful Monkey King, subject of one of the oldest and greatest Chinese fables; and Chin-Kee, a personification of the ultimate negative Chinese stereotype, who is ruining his cousin Danny''s life with his yearly visits. Their lives and stories come together with an unexpected twist in this action-packed modern fable. American Born Chinese is an amazing ride, all the way up to the astonishing climax. American Born Chinese is a 2006 National Book Award Finalist for Young People''s Literature, the winner of the 2007 Eisner Award for Best Graphic Album: New, an Eisner Award nominee for Best Coloring and a 2007 Bank Street - Best Children''s Book of the Year. This title has Common Core Connections', 'https://books.google.com/books/content?id=N0Cw-UWd7mEC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 241, 'http://play.google.com/books/reader?id=N0Cw-UWd7mEC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
