INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('wzDuAAAAMAAJ', 'The Cider House Rules', array['John Irving'], 1985, 'First published in 1985, The Cider House Rules is John Irving''s sixth novel. Set in rural Maine in the first half of this century, it tells the story of Dr. Wilbur Larch--saint and obstetrician, founder and director of the orphanage in the town of St. Cloud''s, ether addict and abortionist. It is also the story of Dr. Larch''s favorite orphan, Homer Wells, who is never adopted. Copyright © Libri GmbH. All rights reserved.', 'https://books.google.com/books/content?id=wzDuAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 566, 'http://play.google.com/books/reader?id=wzDuAAAAMAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
