INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('90JGtAEACAAJ', 'Adventures of Tom Sawyer', array['Mark Twain'], 2018, 'The Adventures of Tom Sawyer by Mark Twain is an 1876 novel about a young boy growing up along the Mississippi River. It is set in the 1840s in the fictional town of St. Petersburg, inspired by Hannibal, Missouri, where Twain lived as a boy', 'https://books.google.com/books/content?id=90JGtAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 232, 'http://play.google.com/books/reader?id=90JGtAEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
