INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('BdFcwgEACAAJ', 'The Adventures of Tom Sawyer', array['Mark Twain'], 2019, 'Here is the story of Tom, Huck, Becky, and Aunt Polly; a tale of adventures, pranks, playing hookey, and summertime fun. Written by the author sometimes called "the Lincoln of literature," The Adventures of Tom Sawyer was surprisingly neither a critical nor a financial success when it was first published in 1876. It was Mark Twain''s first novel. However, since then Tom Sawyer has become his most popular work, enjoying dramatic, film, and even Broadway musical interpretations.', 'https://books.google.com/books/content?id=BdFcwgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 460, 'http://play.google.com/books/reader?id=BdFcwgEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
