         VALUES ('mhxdEQAAQBAJ', 'Osceola The Seminole, or The Red Fawn of the Flower Land', array['Thomas Mayne Reid'], 2023, 'Way ahead of its time, an action-packed adventure written in nineteenth century amazes at the intelligent attitudes of the author towards patriotism and racism. For many kids in previous generations, this was their Harry Potter...you should discover it today. (amazon)', 'https://books.google.com/books/content?id=mhxdEQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 744, 'http://play.google.com/books/reader?id=mhxdEQAAQBAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
