INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('jItODwAAQBAJ', 'The Secret Garden', array['Francis Hodgson Burnett'], 2018, 'Mary Lennox, a sickly and spoiled little girl, is orphaned to dim prospects in a gloomy English manor. Her only friend is a bed-ridden boy named Colin whose prospects may be dimmer than hers. But when Mary finds the key to a Secret Garden, the magical powers of transformation fall within her reach. The Secret Garden is an inspirational tale of transformation and empowerment.', 'https://books.google.com/books/content?id=jItODwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 216, 'http://play.google.com/books/reader?id=jItODwAAQBAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
