INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('p-2s2PWArTQC', 'The Boy in the Striped Pajamas', array['John Boyne'], 2008, 'Two young boys encounter the best and worst of humanity during the Holocaust in this powerful read that USA Today called "as memorable an introduction to the subject as The Diary of Anne Frank.” Berlin, 1942: When Bruno returns home from school one day, he discovers that his belongings are being packed in crates. His father has received a promotion and the family must move to a new house far, far away, where there is no one to play with and nothing to do. A tall fence stretches as far as the eye can see and cuts him off from the strange people in the distance. But Bruno longs to be an explorer and decides that there must be more to this desolate new place than meets the eye. While exploring his new environment, he meets another boy whose life and circumstances are very different from his own, and their meeting results in a friendship that has devastating consequences.', 'https://books.google.com/books/content?id=p-2s2PWArTQC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 242, 'http://play.google.com/books/reader?id=p-2s2PWArTQC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
