           ON CONFLICT DO NOTHING;
INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('gnWeEAAAQBAJ', 'In Search of the Castaways', array['Jules Verne'], 2005, 'A Romantic Narrative of the Loss of Captain Grant of The Brig Britannia and of the Adventures of his Children and Friends in his Discovery and Rescue. In Search of the Castaways (French: Les Enfants du capitaine Grant, lit. ''The Children of Captain Grant'') is a novel by the French writer Jules Verne, published in 1867–68. The book tells the story of the quest for Captain Grant of the Britannia. After finding a bottle the captain had cast into the ocean after the Britannia is shipwrecked, Lord and Lady Glenarvan of Scotland contact Mary and Robert, the young daughter and son of Captain Grant, through an announcement in a newspaper. The government refuses to launch a rescue expedition, but Lord and Lady Glenarvan, moved by the children''s condition, decide to do it by themselves.', 'https://books.google.com/books/content?id=gnWeEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 800, 'http://play.google.com/books/reader?id=gnWeEAAAQBAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
