INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('_j7tAgAAQBAJ', 'Around the World in 80 Days', array['Jules Verne'], 2013, '"All right," said Mr. Fogg; and, turning to the others, he continued: "I have a deposit of twenty thousand at Baring''s which I will willingly risk upon it." "Twenty thousand pounds!" cried Sullivan. "Twenty thousand pounds, which you would lose by a single accidental delay!" "The unforeseen does not exist," quietly replied Phileas Fogg. And with that Phileas Fogg was off on one of the most famous and wonderful adventures of all time. Join him as he has one adventure after another, attempting to do the nearly impossible.', 'https://books.google.com/books/content?id=_j7tAgAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 340, 'http://play.google.com/books/reader?id=_j7tAgAAQBAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
