INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('OJhCDgAAQBAJ', 'Letters to the Lost', array['Brigid Kemmerer'], 2017, 'SSecret letters spark true love in this emotionally compelling romance from the New York Times bestselling author of A Curse So Dark and Lonely, Brigid Kemmerer. Juliet Young always writes letters to her mother, a world-traveling photojournalist. Even after her mother''s death, she leaves letters at her grave. It''s the only way Juliet can cope. Declan Murphy isn''t the sort of guy you want to cross. In the midst of his court-ordered community service at the local cemetery, he''s trying to escape the demons of his past. When Declan reads a haunting letter left beside a grave, he can''t resist writing back. Soon, he''s opening up to a perfect stranger, and their connection is immediate. But neither Declan nor Juliet knows that they''re not actually strangers. When life at school interferes with their secret life of letters, sparks will fly as Juliet and Declan discover truths that might tear them apart.', 'https://books.google.com/books/content?id=OJhCDgAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 403, 'http://play.google.com/books/reader?id=OJhCDgAAQBAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
