INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('S_aIKYEH6xwC', 'The Unbecoming of Mara Dyer', array['Michelle Hodkin'], 2011, '“Haunting and dreamlike.” —Cassandra Clare, author of the New York Times bestselling Moral Instruments series A grieving teen plagued by visions tries to determine if she’s hallucinating or being haunted in this first book in the Mara Dyer young adult thriller trilogy that “will satisfy mystery lovers, dark fantasy seekers, horror believers, and readers who have a knack for romance” (VOYA). When Mara Dyer wakes up in a hospital, she learns that she’s the sole survivor of an accident that killed her boyfriend and closest friends. She can’t remember the building collapsing—or why they were at the old asylum in the first place, and she doesn’t put up much of a fight when her mom decides it would be best for the family to make a fresh start, leaving Rhode Island for Miami. At her new elite private school, the popular kids immediately single Mara out and bully her relentlessly—except for Noah, a charming bad boy with a knack for drawing Mara out of her shell. But Mara can’t leave her ghosts behind. Her mom tells her she’s suffering from post-traumatic stress disorder, that the razed buildings and dead friends Mara sees are hallucinations, but Mara can’t help but wonder if there’s more to her visions. When people around her begin dying, Mara becomes even more desperate to determine reality from nightmare. With Noah’s help, can Mara separate what’s real from what’s imagined…and what’s very, very dangerous?', 'https://books.google.com/books/content?id=S_aIKYEH6xwC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 480, 'http://play.google.com/books/reader?id=S_aIKYEH6xwC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
