         VALUES ('IiLlZh6U5tAC', 'Dragonsinger', array['Anne McCaffrey'], 2003, 'Award-winning fantasy author Anne McCaffrey returns with her bestselling Harper Hall Trilogy, wonder-filled imaginative classics now available in digest format.', 'https://books.google.com/books/content?id=IiLlZh6U5tAC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 288, 'http://play.google.com/books/reader?id=IiLlZh6U5tAC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
