INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('MC5EEAAAQBAJ', 'Random Minis: All the Bright Places', array['Jennifer Niven'], 2019, 'The New York Times bestseller All the Bright Places in a groundbreaking new mini format, perfect for on-the-go reading! Theodore Finch is fascinated by death. Every day he thinks of ways he might die, but every day he also searches for--and manages to find--something to keep him here, and alive, and awake. Violet Markey lives for the future, counting the days until graduation, when she can escape her small Indiana town and her aching grief in the wake of her sister''s death. When Finch and Violet meet on the ledge of the bell tower at school--six stories above the ground--it''s unclear who saves whom. Soon it''s only with Violet that Finch can be himself. And it''s only with Finch that Violet forgets to count away the days and starts living them. But as Violet''s world grows, Finch''s begins to shrink. . . . All the Bright Places is a heart-wrenching, unflinching story of love shared, life lived, and two teens who find each other while standing on the edge. Random Minis are super-light, cellphone-sized, unabridged books made to fit into a pocket or one hand without sacrificing readability. Other titles include Every Day by David Levithan, Dear Martin by Nic Stone, Everything, Everything by Nicola Yoon, I Am Not Your Perfect Mexican Daughter by Erika Sánchez, and We Were Liars by E. Lockhart.', 'https://books.google.com/books/content?id=MC5EEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 721, 'http://play.google.com/books/reader?id=MC5EEAAAQBAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
