INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('2tkq0bLgDJQC', 'A Tale of Two Cities', array['Charles Dickens'], 1996, 'Must one honorable man pay for the sins of his cruel, aristocratic family? Can an old man brutally wronged by that family find forgiveness before it''s too late? And will history--the sweeping violence of the French Revolution--force father to betray child in his search for vengeance? A Tale of Two Cities is Charles Dickens''s immortal story of love and ultimate sacrifice.', 'https://books.google.com/books/content?id=2tkq0bLgDJQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 68, 'http://play.google.com/books/reader?id=2tkq0bLgDJQC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
