INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('O1SVzQEACAAJ', 'The Adventures of Tom Sawyer Illustrated', array['Mark Twain'], 2020, 'The Adventures of Tom Sawyer by Mark Twain is an 1876 novel about a young boy growing up along the Mississippi River. It is set in the 1840s in the fictional town of St. Petersburg, inspired by Hannibal, Missouri, where Twain lived as a boy.In the novel Tom Sawyer has several adventures, often with his friend Huckleberry Finn. Originally a commercial failure, the book ended up being the best selling of any of Twain''s works during his lifetime.', 'https://books.google.com/books/content?id=O1SVzQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 276, 'http://play.google.com/books/reader?id=O1SVzQEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
