INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('6kjtZwEACAAJ', 'The Blue Lotus', array['Hergé'], 2006, 'An authentic facsimile of the original, with a brand new translation. Tintin travels to China in a tale considered Herge''s first masterpiece, as well as Tintin''s only foray into actual history, the Sino-Japanese conflicts of the early 1930s. political tensions combined wihth chilling threats of drugs give the story an especially realistic sense of danger. Herge paints a vivid picture of China and denounces ethnic prejudices - through ironically, his depiction of the Japanese businessman is grotesque.', 'https://books.google.com/books/content?id=6kjtZwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 'http://play.google.com/books/reader?id=6kjtZwEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
