INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('rm-6BAAAQBAJ', 'The Daughter of Odren', array['Ursula K. Le Guin'], 2014, 'The Daughter of Odren is a short story of betrayal and revenge set in the world of Earthsea, in which Weed, the daughter of Lord Garnet, waits for the day she will have her father back. For fourteen years, Weed, as she is called, the daughter of Lord Garnet, has brought offerings to the standing stone. Alone in a shallow valley, she implores the stone not to forget her. To remember who he is and the life he led. To wait until the day he will be avenged. Now the day has finally arrived. After fourteen long years of waiting, he will have his revenge and she will have her father back. Or will she? Master storyteller Ursula LeGuin takes readers back to Earthsea with this hauntingly beautiful story of betrayal and revenge.', 'https://books.google.com/books/content?id=rm-6BAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 43, 'http://play.google.com/books/reader?id=rm-6BAAAQBAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
