INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('DNNXAAAAYAAJ', 'The Giver', array['Lois Lowry'], 2002, 'Lois Lowry''s The Giver is the quintessential dystopian novel, followed by its remarkable companions, Gathering Blue, Messenger, and Son. Jonas''s world is perfect. Everything is under control. There is no war or fear of pain. There are no choices. Every person is assigned a role in the community. When Jonas turns 12 he is singled out to receive special training from The Giver. The Giver alone holds the memories of the true pain and pleasure of life. Now, it is time for Jonas to receive the truth. There is no turning back.', 'https://books.google.com/books/content?id=DNNXAAAAYAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 196, 'http://play.google.com/books/reader?id=DNNXAAAAYAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
