INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('rlaPDQAAQBAJ', 'Two Boys Kissing', array['David Levithan'], 2015, 'NEW YORK TIMES BESTSELLER • STONEWALL HONOR BOOK • LAMBDA LITERARY AWARD WINNER • NATIONAL BOOK AWARD LONGLIST "You have to read this.” —Rainbow Rowell, bestselling author of Eleanor & Park and Carry On From the New York Times bestselling author of Every Day, this love story of shared humanity and history Hypable calls "an interconnecting web that will leave you emotionally exhausted and absolutely thrilled to have read something so beautiful and unique." Based on true events—and narrated by a Greek Chorus of the generation of gay men lost to AIDS—Two Boys Kissing follows Harry and Craig, two seventeen-year-olds who are about to take part in a 32-hour marathon of kissing to set a new Guinness World Record. While the two increasingly dehydrated and sleep-deprived boys are locking lips, they become a focal point in the lives of other teens dealing with universal questions of love, identity, and belonging.', 'https://books.google.com/books/content?id=rlaPDQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 226, 'http://play.google.com/books/reader?id=rlaPDQAAQBAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
