INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('VVOvC28zSJkC', 'Ties That Bind, Ties That Break', array['Lensey Namioka'], 2007, 'Third Sister in the Tao family, Ailin has watched her two older sisters go through the painful process of having their feet bound. In China in 1911, all the women of good families follow this ancient tradition. But Ailin loves to run away from her governess and play games with her male cousins. Knowing she will never run again once her feet are bound, Ailin rebels and refuses to follow this torturous tradition. As a result, however, the family of her intended husband breaks their marriage agreement. And as she enters adolescence, Ailin finds that her family is no longer willing to support her. Chinese society leaves few options for a single woman of good family, but with a bold conviction and an indomitable spirit, Ailin is determined to forge her own destiny. Her story is a tribute to all those women whose courage created new options for the generations who came after them.', 'https://books.google.com/books/content?id=VVOvC28zSJkC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 162, 'http://play.google.com/books/reader?id=VVOvC28zSJkC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
