INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('h6ZIWfOiR24C', 'The Mediator #3: Reunion', array['Meg Cabot'], 2009, 'Reunion is the third book in the thrilling, romantic Mediator series, from the New York Times bestselling author of the Princess Diaries, Meg Cabot. The RLS Angels are out for blood, and only Suze can stop them—since she''s the only one who can see them. The four ghostly teenagers died in a terrible car accident, for which they blame Suze''s classmate Michael...and they''ll stop at nothing until he''s joined them in the realm of the dead. As Suze desperately fends off each attempt on Michael''s life, she finds she can relate to the Angels'' fury. Because their deaths turn out not to have been accidental at all. And their killer is only too willing to strike again. Don''t miss the delightfully funny supernatural Mediator series, from New York Times bestselling author Meg Cabot. A Hot Ghost in Her Bedroom: Suze''s biggest secret isn’t that she sees ghosts—it’s that she’s falling for one. Jesse has been dead for 150 years, and he’s the only one who truly understands her. A High School Whodunit: When four popular teens die in a fiery crash, they come back blaming classmate Michael. They won’t rest until he joins them, and it’s up to Suze to stop them. Reluctant Hero: Suze would rather be at the beach, but when the ghosts get violent, she’s the only one who can fight back—even if it means protecting the school geek. A Killer Twist: As Suze digs deeper, she realizes the car crash was no accident. Now she’s hunting a murderer who is hiding in plain sight and willing to kill again.', 'https://books.google.com/books/content?id=h6ZIWfOiR24C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 308, 'http://play.google.com/books/reader?id=h6ZIWfOiR24C&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
