INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('2j7PDwAAQBAJ', 'Fright Night', array['Maren Stoffels'], 2020, 'Spending the night in the woods with your friends is not a good idea in this scary thriller by the author of ESCAPE ROOM--a Halloween must-read. Sofia isn''t so sure about Fright Night. When she suggested it to her friends, she was only thinking of it as an excuse to get closer to Dylan. Now that it''s happening, she''s worried that spending the night in a deserted forest is a bad idea. But it''s totally safe--there''s even a safe word if things get too intense. And they do. Sofia and her friends are forced to face their greatest fears, and suddenly? It''s too late to turn back. Underlined is a line of totally addictive romance, thriller, and horror titles coming to you fast and furious each month. Enjoy everything you want to read the way you want to read it.', 'https://books.google.com/books/content?id=2j7PDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 226, 'http://play.google.com/books/reader?id=2j7PDwAAQBAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
