INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('s9taBIMtYvcC', 'My Grandfather''s Son', array['Clarence Thomas'], 2007, 'Provocative, inspiring, and unflinchingly honest, My Grandfather''s Son is the story of one of America''s most remarkable and controversial leaders, Supreme Court justice Clarence Thomas, told in his own words. Thomas was born in rural Georgia on June 23, 1948, into a life marked by poverty and hunger. His parents divorced when Thomas was still a baby, and his father moved north to Philadelphia, leaving his young mother to raise him and his brother and sister on the ten dollars a week she earned as a maid. At age seven, Thomas and his six-year-old brother were sent to live with his mother''s father, Myers Anderson, and her stepmother in their Savannah home. It was a move that would forever change Thomas''s life. His grandfather, whom he called "Daddy," was a black man with a strict work ethic, trying to raise a family in the years of Jim Crow. Thomas witnessed his grandparents'' steadfastness despite injustices, their hopefulness despite bigotry, and their deep love for their country. His own quiet ambition would propel him to Holy Cross and Yale Law School, and eventually—despite a bitter, highly contested public confirmation—to the highest court in the land. In this candid and deeply moving memoir, a quintessential American tale of hardship and grit, Clarence Thomas recounts his astonishing journey for the first time, and pays homage to the man who made it possible. Intimately and eloquently, Thomas speaks out, revealing the pieces of his life he holds dear, detailing the suffering and injustices he has overcome, including the acrimonious and polarizing Senate hearing involving a former aide, Anita Hill, and the depression and despair it created in his own life and the lives of those closest to him. My Grandfather''s Son is the story of a determined man whose faith, courage, and perseverance inspired him to rise up against all odds and achieve his dreams.', 'https://books.google.com/books/content?id=s9taBIMtYvcC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 308, 'http://play.google.com/books/reader?id=s9taBIMtYvcC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
