INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('63LUBQAAQBAJ', 'After the White House', array['Max J. Skidmore'], 2004, 'What exactly has Bill Clinton been doing since he left office? What can he expect to accomplish? What have his predecessors in his position done? Many presidents have had enormous impacts on the course of history after their terms ended, but not until After the White House by Max J. Skidmore has their role been examined. Thirty-two completed their terms. Four became presidential candidates again (one was even elected), two served in Congress, one abandoned his country to accept election to the Confederate Congress, one became Chief Justice, and one has the unique distinction of having his First Lady become a United States senator. Former presidents almost always remain influential, but their post-term activities have received little attention or scrutiny until now.', 'https://books.google.com/books/content?id=63LUBQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 207, 'http://play.google.com/books/reader?id=63LUBQAAQBAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
