INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('yXl2AAAAMAAJ', 'Civil War to the Bloody End', array['Jerry D. Thompson'], 2006, '"If President Lincoln could have unmade a general, perhaps he would have started with Samuel Peter "Sourdough" Heintzelman, whose early military successes were overshadowed by a prickly disposition and repeated Union defeats during the Civil War." "By the time his friend Robert E. Lee left Arlington to lead a Rebel army against the bluecoats, Heintzelman had already seen duty in Mexico, established Fort Yuma in California in 1850, mined for silver in Arizona, and ably led U.S. forces on the Texas-Mexico border during the 1859-60 Cortina War. During the Civil War, he was in the forefront of the fighting at First Bull Run and the disastrous 1862 Peninsula Campaign. He commanded the III Corps of the Army of the Potomac at the siege of Yorktown and in the ferocious fighting at Williamsburg, Fair Oaks, Oak Grove, Savage''s Station, Glendale, and Malvern Hill. Although he aspired to succeed Gen. George B. McClellan, he was relieved of his command after his troops were badly mauled at Second Bull Run. After demonstrating his inability to guard the southern approaches to Washington, D.C., from Virginia guerillas, he spent the latter part of the war administering prison camps in the Midwest, keeping a watchful eye on Copperhead subversives, and quarreling with more than one disgruntled governor. In early Reconstruction Texas, Heintzelman struggled with the conflict between former Secessionists and Radical Republicans."--BOOK JACKET.', 'https://books.google.com/books/content?id=yXl2AAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 472, 'http://play.google.com/books/reader?id=yXl2AAAAMAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
