           ON CONFLICT DO NOTHING;
INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('PmiFb1e1Fm4C', 'The Music of Bill Monroe', array['Neil V. Rosenberg','Charles K. Wolfe'], 2007, 'Spanning over 1,000 separate performances, The Music of Bill Monroe presents a complete chronological list of all of Bill Monroe’s commercially released sound and visual recordings. Each chapter begins with a narrative describing Monroe’s life and career at that point, bringing in producers, sidemen, and others as they become part of the story. The narratives read like a “who’s who” of bluegrass, connecting Monroe to the music’s larger history and containing many fascinating stories. The second part of each chapter presents the discography. Information here includes the session’s place, date, time, and producer; master/matrix numbers, song/tune titles, composer credits, personnel, instruments, and vocals; and catalog/release numbers and reissue data. The only complete bio-discography of this American musical icon, The Music of Bill Monroe is the starting point for any study of Monroe’s contributions as a composer, interpreter, and performer.', 'https://books.google.com/books/content?id=PmiFb1e1Fm4C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 384, 'http://play.google.com/books/reader?id=PmiFb1e1Fm4C&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
