INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('6nwEAQAAIAAJ', 'The Dangerous Summer', array['Ernest Hemingway'], 1985, 'The Dangerous Summer is Hemingway''s firsthand chronicle of a brutal season of bullfights. In this vivid account, Hemingway captures the exhausting pace and pressure of the season, the camaraderie and pride of the matadors, and the mortal drama as in fight after fight the rival matadors try to outdo each other with ever more daring performances. At the same time Hemingway offers an often complex and deeply personal self-portrait that reveals much about one of the twentieth century''s preeminent writers.', 'https://books.google.com/books/content?id=6nwEAQAAIAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 264, 'http://play.google.com/books/reader?id=6nwEAQAAIAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
