INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('t0mK_dmhRioC', 'Francis Crick', array['Matt Ridley'], 2006, 'Francis Crick, who died at the age of eighty-eight in 2004, will be bracketed with Galileo, Darwin, and Einstein as one of the great scientists of all time. Between 1953 and 1966 he made and led a revolution in biology by discovering, quite literally, the secret of life: the digital cipher at the heart of heredity that distinguishes living from non-living things -- the genetic code. His own discoveries -- though he always worked with one other partner and did much of his thinking in conversation -- include not only the double helix but the whole mechanism of protein synthesis, the three-letter nature of the code, and much of the code itself. Matt Ridley''s biography traces Crick''s life from middle-class mediocrity in the English Midlands, through a lackluster education and six years designing magnetic mines for the Royal Navy, to his leap into biology at the age of thirty-one. While at Cambridge, he suddenly began to display the unique visual imagination and intense tenacity of thought that would allow him to see the solutions to several great scientific conundrums -- and to see them long before most biologists had even conceived of the problems. Having set out to determine what makes living creatures alive and having succeeded, he immigrated at age sixty to California and turned his attention to the second question that had fascinated him since his youth: What makes conscious creatures conscious? Time ran out before he could find the answer.', 'https://books.google.com/books/content?id=t0mK_dmhRioC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 227, 'http://play.google.com/books/reader?id=t0mK_dmhRioC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
