         VALUES ('q5JFGQXUYx4C', 'Actors on Red Alert', array['Anthony Slide'], 1999, 'The anti-Communist hysteria that began in the 1930s was further empowered in 1938 when the House of Representatives established the House Committee on UnAmerican Activities. Soon thereafter, the creation of the blacklist in the late 1940s brought the Hollywood film and television community into the fold. Provocatively capturing the controversy and sentiments surrounding this period of political imbalance, Actors on Red Alert explores the repercussions of the blacklist through career interviews with five prominent actors and actresses.', 'https://books.google.com/books/content?id=q5JFGQXUYx4C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 206, 'http://play.google.com/books/reader?id=q5JFGQXUYx4C&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
