         VALUES ('rxQaAQAAIAAJ', 'The Quotable Jefferson', array['Thomas Jefferson'], 2006, 'More than any other Founding Father, Thomas Jefferson made his reputation on the brilliance of his writing, and few writers have said so much on so many subjects. This comprehensive book demonstrates that thoroughly.', 'https://books.google.com/books/content?id=rxQaAQAAIAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 646, 'http://play.google.com/books/reader?id=rxQaAQAAIAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
