INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('YXdoAAAAMAAJ', 'The Resistible Rise of Benito Mussolini', array['Tom Behan'], 2003, 'In 1920 Italy was on the verge of a socialist revolution. Just two years later Benito Mussolini''s fascists took power and ushered in an era of repression, war and, ultimately, genocide. In this enthralling book Tom Behan shows how a group of militant anti-fascists came close to stopping Mussolini and changing the course of history. Tragically, their bravery was undermined by a combination of the left''s sectarianism and naive faith in the impartiality of the police. An important and detailed analysis of a period of Italian history which is often ignored'' - WSF''', 'https://books.google.com/books/content?id=YXdoAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 148, 'http://play.google.com/books/reader?id=YXdoAAAAMAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
