INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('VvNRN4uV9PYC', 'Dear Yeats, Dear Pound, Dear Ford', array['Richard Londraville','Janis Londraville'], 2001, 'Jeanne Foster challenged the accepted role for women at the turn of the twentieth century. Born on a hardscrabble farm in the Adirondack Mountains in 1879, she was hailed as an important voice in American poetry by 1916 when her first books of verse, Neighbors of Yesterday and Wild Apples were published. She had early success as a model—she was the Harrison Fisher girl of 1903—and later became a journalist for the American Review of Reviews. In 1918, she met John Quinn, patron of the arts, which placed her in the middle of some of the most important literary and artistic movements in the twentieth century. She counted among her friends John Butler and William Butler Yeats, Ezra Pound, James Joyce, Ford Madox Ford, Pablo Picasso, and Constantin Brancusi. This book reveals her dark affair with Aleister Crowley and her great friendship with Tomas Masaryk of Czechoslovakia. Today, Jeanne Foster lies buried in Chestertown, New York, next to her old friend John Butler Yeats.', 'https://books.google.com/books/content?id=VvNRN4uV9PYC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 332, 'http://play.google.com/books/reader?id=VvNRN4uV9PYC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
