INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('SVR2cjWptCAC', 'Damascus', array['Ross Burns'], 2005, 'This is the first book in English to relate the history of Damascus, bringing out the crucial role the city has played at many points in the region''s past. Damascus traces the history of this colourful, significant and complex city through its physical development, from the city''s emergence in around 7000 BC through the changing cavalcade of Aramaean, Persian, Greek, Roman, Byzantine, Arab, Mongol and French rulers right up to the end of Turkish control in 1918. In Damascus, every layer of the history has built precisely on top of its predecessors for at least three millennia, leaving a detailed archaeological record of one of the oldest continuously inhabited cities in the world. The book looks particularly at the interplay between the western and eastern influences that have provided Damascus with such a rich past, and how this perfectly encapsulates the forces that have played over the Middle East as a whole from the earliest recorded times to the present. Lavishly illustrated, Damascus: A History is a compelling and unique exploration of a fascinating city.', 'https://books.google.com/books/content?id=SVR2cjWptCAC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 409, 'http://play.google.com/books/reader?id=SVR2cjWptCAC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
