INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('jsm2DAEACAAJ', 'Uncle Tom''s Cabin', array['Harriet Beecher Stowe','Harriet Elizabeth (Beecher) Stowe'], 1908, 'Having run up large debts, a Kentucky farmer named Arthur Shelby faces the prospect of losing everything he owns. Though he and his wife, Emily Shelby, have a kindhearted and affectionate relationship with their slaves, Shelby decides to raise money by selling two of his slaves to Mr. Haley, a coarse slave trader. The slaves in question are Uncle Tom, a middle-aged man with a wife and children on the farm, and Harry, the young son of Mrs. Shelby''s maid Eliza. When Shelby tells his wife about his agreement with Haley, she is appalled because she has promised Eliza that Shelby would not sell her son.', 'https://books.google.com/books/content?id=jsm2DAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 358, 'http://play.google.com/books/reader?id=jsm2DAEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
