INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('8lm0BubW8oUC', 'Harlem Crossroads', array['Sara Blair'], 2007, '"The Harlem riot of 1935 not only signaled the end of the Harlem Renaissance; it made black America''s cultural capital an icon for the challenges of American modernity. Luring photographers interested in socially conscious, journalistic and aesthetic representation, post-Renaissance Harlem helped give rise to America''s full-blown image culture and its definitive genre, documentary. Arguing for Harlem as a crossroads between writers and the image, Sara Blair explores its power for canonical writers, whose work was responsive to the changing meanings and uses of photographs. She examines literary engagements with photography from the 1930s to the 1970s and beyond." --Book Jacket.', 'https://books.google.com/books/content?id=8lm0BubW8oUC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 392, 'http://play.google.com/books/reader?id=8lm0BubW8oUC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
