INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('s2aN5ETA_GQC', 'A Century of Spies', array['Jeffery T. Richelson'], 1997, 'Here is the ultimate inside history of twentieth-century intelligence gathering and covert activity. Unrivalled in its scope and as readable as any spy novel, A Century of Spies travels from tsarist Russia and the earliest days of the British Secret Service to the crises and uncertainties of today''s post-Cold War world, offering an unsurpassed overview of the role of modern intelligence in every part of the globe. From spies and secret agents to the latest high-tech wizardry in signals and imagery surveillance, it provides fascinating, in-depth coverage of important operations of United States, British, Russian, Israeli, Chinese, German, and French intelligence services, and much more. All the key elements of modern intelligence activity are here. An expert whose books have received high marks from the intelligence and military communities, Jeffrey Richelson covers the crucial role of spy technology from the days of Marconi and the Wright Brothers to today''s dazzling array of Space Age satellites, aircraft, and ground stations. He provides vivid portraits of spymasters, spies, and defectors--including Sidney Reilly, Herbert Yardley, Kim Philby, James Angleton, Markus Wolf, Reinhard Gehlen, Vitaly Yurchenko, Jonathan Pollard, and many others. Richelson paints a colorful portrait of World War I''s spies and sabateurs, and illuminates the secret maneuvering that helped determine the outcome of the war on land, at sea, and on the diplomatic front; he investigates the enormous importance of intelligence operations in both the European and Pacific theaters in World War II, from the work of Allied and Nazi agents to the "black magic" of U.S. and British code breakers; and he gives us a complete overview of intelligence during the length of the Cold War, from superpower espionage and spy scandals to covert action and secret wars. A final chapter probes the still-evolving role of intelligence work in the new world of disorder and ethnic conflict, from the high-tech wonders of the Gulf War to the surprising involvement of the French government in industrial espionage. Comprehensive, authoritative, and addictively readable, A Century of Spies is filled with new information on a variety of subjects--from the activities of the American Black Chamber in the 1920s to intelligence collection during the Cuban missile crisis to Soviet intelligence and covert action operations. It is an essential volume for anyone interested in military history, espionage and adventure, and world affairs.', 'https://books.google.com/books/content?id=s2aN5ETA_GQC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 545, 'http://play.google.com/books/reader?id=s2aN5ETA_GQC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
INSERT INTO category (categoryName) VALUES ('History') ON CONFLICT DO NOTHING;
INSERT INTO bookToCategory (bookId, categoryId)
           SELECT 's2aN5ETA_GQC', categoryId FROM category WHERE categoryName = 'History'
           ON CONFLICT DO NOTHING;
INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('y_SLDQAAQBAJ', 'The Cold War', array['Stephen E. Ambrose','Caleb Carr','Thomas Fleming','Victor Davis Hanson'], 2006, 'Even fifteen years after the end of the Cold War, it is still hard to grasp that we no longer live under its immense specter. For nearly half a century, from the end of World War II to the early 1990s, all world events hung in the balance of a simmering dispute between two of the greatest military powers in history. Hundreds of millions of people held their collective breath as the United States and the Soviet Union, two national ideological entities, waged proxy wars to determine spheres of influence–and millions of others perished in places like Korea, Vietnam, and Angola, where this cold war flared hot. Such a consideration of the Cold War–as a military event with sociopolitical and economic overtones–is the crux of this stellar collection of twenty-six essays compiled and edited by Robert Cowley, the longtime editor of MHQ: The Quarterly Journal of Military History. Befitting such a complex and far-ranging period, the volume’s contributing writers cover myriad angles. John Prados, in “The War Scare of 1983,” shows just how close we were to escalating a war of words into a nuclear holocaust. Victor Davis Hanson offers “The Right Man,” his pungent reassessment of the bellicose air-power zealot Curtis LeMay as a man whose words were judged more critically than his actions. The secret war also gets its due in George Feiffer’s “The Berlin Tunnel,” which details the charismatic C.I.A. operative “Big Bill” Harvey’s effort to tunnel under East Berlin and tap Soviet phone lines–and the Soviets’ equally audacious reaction to the plan; while “The Truth About Overflights,” by R. Cargill Hall, sheds light on some of the Cold War’s best-kept secrets. The often overlooked human cost of fighting the Cold War finds a clear voice in “MIA” by Marilyn Elkins, the widow of a Navy airman, who details the struggle to learn the truth about her husband, Lt. Frank C. Elkins, whose A-4 Skyhawk disappeared over Vietnam in 1966. In addition there are profiles of the war’s “front lines”–Dien Bien Phu, the Cuban Missile Crisis, the Bay of Pigs–as well as of prominent military and civil leaders from both sides, including Harry S. Truman, Nikita Khrushchev, Dean Acheson, Gen. Douglas MacArthur, Richard M. Nixon, Gen. Vo Nguyen Giap, and others. Encompassing so many perspectives and events, The Cold War succeeds at an impossible task: illuminating and explaining the history of an undeclared shadow war that threatened the very existence of humankind.', 'https://books.google.com/books/content?id=y_SLDQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 496, 'http://play.google.com/books/reader?id=y_SLDQAAQBAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
INSERT INTO category (categoryName) VALUES ('History') ON CONFLICT DO NOTHING;
INSERT INTO bookToCategory (bookId, categoryId)
           SELECT 'y_SLDQAAQBAJ', categoryId FROM category WHERE categoryName = 'History'
           ON CONFLICT DO NOTHING;
INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('vw5dzCOcRWsC', 'American Refugee Policy and European Jewry, 1933-1945', array['Richard Bretman','Alan M. Kraut'], 1987, 'How does one explain America''s failure to take bold action to resist the Nazi persecution and murder of European Jews? In contrast to recent writers who place the blame on anti-Semitism in American society at large and within the Roosevelt administration in particular, Richard Breitman and Alan M. Kraut seek the answer in a detailed analysis of American political realities and bureaucratic processes. Drawing on exhaustive archival research, the authors describe and analyze American immigration policy as well as rescue and relief efforts directed toward European Jewry between 1933 and 1945. They contend that U.S. policy was the product of preexisting restrictive immigration laws; an entrenched State Department bureaucracy committed to a narrow defense of American interests; public opposition to any increase in immigration; and the reluctance of Franklin D. Roosevelt to accept the political risks of humanitarian measures to benefit the European Jews. The authors find that the bureaucrats who made and implemented refugee policy were motivated by institutional priorities and reluctance to take risks, rather than by moral or humanitarian concerns.', 'https://books.google.com/books/content?id=vw5dzCOcRWsC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 328, 'http://play.google.com/books/reader?id=vw5dzCOcRWsC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
INSERT INTO category (categoryName) VALUES ('History') ON CONFLICT DO NOTHING;
INSERT INTO bookToCategory (bookId, categoryId)
           SELECT 'vw5dzCOcRWsC', categoryId FROM category WHERE categoryName = 'History'
           ON CONFLICT DO NOTHING;
INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('plppBox-uAYC', 'Drama, Play, and Game', array['Lawrence M. Clopper'], 2001, 'How was it possible for drama, especially biblical representations, to appear in the Christian West given the church''s condemnation of the theatrum of the ancient world?In a book with radical implications for the study of medieval literature, Lawrence Clopper resolves this perplexing question. Drama, Play, and Game demonstrates that the theatrum repudiated by medieval clerics was not "theater" as we understand the term today. Clopper contends that critics have misrepresented Western stage history because they have assumed that theatrum designates a place where drama is performed. While theatrum was thought of as a site of spectacle during the Middle Ages, the term was more closely connected with immodest behavior and lurid forms of festive culture. Clerics were not opposed to liturgical representations in churches, but they strove ardently to suppress May games, ludi, festivals, and liturgical parodies. Medieval drama, then, stemmed from a more vernacular tradition than previously acknowledged-one developed by England''s laity outside the boundaries of clerical rule.', 'https://books.google.com/books/content?id=plppBox-uAYC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 356, 'http://play.google.com/books/reader?id=plppBox-uAYC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
INSERT INTO category (categoryName) VALUES ('Drama') ON CONFLICT DO NOTHING;
