INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('Kk5LQU_O5ZsC', 'Violent Entrepreneurs', array['Vadim Volkov'], 2002, 'This book explores the economic uses of violence and coercion in Russia in the 1990s through interviews with members of criminal groups, heads of protection companies, law enforcement employees and businesspeople. It also uses journalistic and anecdotal evidence. It shows that violence has played a crucial role in creating the institutions of a new market economy, and describes the competition among so-called violence-managing agencies which have multiplied with the liberal reforms of the early 1990s. Examples of these organizations include criminal groups, private security services, private protection companies, and informal protective agencies associated with the state. The book also examines the organizational bases of violence-prone groups in sports clubs (particularly martial arts clubs), associations for veterans of the Soviet-Afghan war, ethnic gangs, and regionally based social groups. Some groups wore state uniforms and others did not, but all of their members spoke and acted essentially the same and were engaged in the same activities: intimidation, protection, information gathering, dispute management, contract enforcement, and taxation. Each group controlled the same resource-organized violence.', 'https://books.google.com/books/content?id=Kk5LQU_O5ZsC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 232, 'http://play.google.com/books/reader?id=Kk5LQU_O5ZsC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
INSERT INTO category (categoryName) VALUES ('History') ON CONFLICT DO NOTHING;
