           SELECT 'Kk5LQU_O5ZsC', categoryId FROM category WHERE categoryName = 'History'
           ON CONFLICT DO NOTHING;
INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('xA7YAAAAMAAJ', 'In the Shadow of the Prophet', array['Milton Viorst'], 1998, 'As war, pestilence, and famine spread through Europe in the Middle Ages, so did reports of miracles, of hopeless victims wondrously saved from disaster. These "rescue miracles," recorded by over one hundred fourteenth-century cults, are the basis of Michael Goodich''s account of the miraculous in everyday medieval life. Rescue miracles offer a wide range of voices rarely heard in medieval history, from women and children to peasants and urban artisans. They tell of salvation not just from the ravages of nature and war, but from the vagaries of a violent society—crime, unfair judicial practices, domestic squabbles, and communal or factional conflict. The stories speak to a collapse of confidence in decaying institutions, from the law to the market to feudal authority. Particularly, the miraculous escapes documented during the Hundred Years'' War, the Italian communal wars, and other conflicts are vivid testimony to the end of aristocratic warfare and the growing victimization of noncombatants. Miracles, Goodich finds, represent the transcendent and unifying force of faith in a time of widespread distress and the hopeless conditions endured by the common people of the Middle Ages. Just as the lives of the saints, once dismissed as church propaganda, have become valuable to historians, so have rescue miracles, as evidence of an underlying medieval mentalite. This work expands our knowledge of that state of mind and the grim conditions that colored and shaped it.', 'https://books.google.com/books/content?id=xA7YAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 372, 'http://play.google.com/books/reader?id=xA7YAAAAMAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
INSERT INTO category (categoryName) VALUES ('History') ON CONFLICT DO NOTHING;
INSERT INTO bookToCategory (bookId, categoryId)
           SELECT 'xA7YAAAAMAAJ', categoryId FROM category WHERE categoryName = 'History'
           ON CONFLICT DO NOTHING;
INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('2DC1AAAAIAAJ', 'Bitter Glory', array['Richard M. Watt'], 1979, '"In Bitter Glory, Richard M. Watt tells the story of the independent Poland of 1918-1939. He also gives the definitive account in English of the dominant figure in this story, the Polish freedom fighter and strongman Józef Piłsudski. Watt describes the underground warfare Piłsudski waged against czarist rule; how the Poles deftly exploited World War I to achieve independence; the problems that racked the new state; the country''s drift toward fascism; and its debacle at the hands of the Nazis, in which Poland lost its freedom." --', 'https://books.google.com/books/content?id=2DC1AAAAIAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 552, 'http://play.google.com/books/reader?id=2DC1AAAAIAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
