         VALUES ('C56qIArVlyUC', 'National Security Law and the Power of the Purse', array['William C. Banks','Peter Raven-Hansen'], 1994, 'This power, by necessity and preference, has become the central congressional tool for participating in national security policy. Inevitably attacks on policy are transformed into attacks on the making and effects of appropriations.', 'https://books.google.com/books/content?id=C56qIArVlyUC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 278, 'http://play.google.com/books/reader?id=C56qIArVlyUC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
