INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('4ehJAAAAMAAJ', 'The Wizard War', array['Reginald Victor Jones'], 1978, '"Reginald Jones was nothing less than a genius. And his appointment to the Intelligence Section of Britain''s Air Ministry in 1939 led to some of the most astonishing scientific and technological breakthroughs of the Second World War. In Most Secret War he details how Britain stealthily stole the war from under the Germans'' noses by outsmarting their intelligence at every turn. He tells of the ''battle of the beams''; detecting and defeating flying bombs; using chaff to confuse radar; and many other ingenious ideas and devices. Jones was the man with the plan to save Britain and his story makes for riveting reading."-- Amazon.', 'https://books.google.com/books/content?id=4ehJAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 614, 'http://play.google.com/books/reader?id=4ehJAAAAMAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
