INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('QgzBqhbdlvUC', 'Switch', array['Chip Heath','Dan Heath'], 2010, '#1 NEW YORK TIMES BESTSELLER • ONE MILLION COPIES SOLD! The ultimate guide to making changes and following through, from the authors of Made to Stick and Decisive—hailed as “witty and instructive” (The Wall Street Journal), “packed with examples and hands-on tools that will get you moving right away” (BusinessWeek) Why is it so hard to make lasting changes in our companies, in our communities, and in our own lives? The primary obstacle is a conflict that''s built into our brains, say Chip and Dan Heath. Psychologists have discovered that our minds are ruled by two different systems—the rational mind and the emotional mind—that compete for control. The rational mind wants a great beach body; the emotional mind wants that Oreo cookie. The rational mind wants to change something at work; the emotional mind loves the comfort of the existing routine. This tension can doom a change effort—but if it is overcome, change can come quickly. In Switch, the Heaths show how everyday people—employees and managers, parents and nurses—have united both minds and, as a result, achieved dramatic results: • the lowly medical interns who managed to defeat an entrenched, decades-old medical practice that was endangering patients • the home-organizing guru who developed a simple technique for overcoming the dread of housekeeping • the manager who transformed a lackadaisical customer-support team into service zealots by removing a standard tool of customer service In a compelling, story-driven narrative, the Heaths bring together decades of counterintuitive research in psychology, sociology, and other fields to shed new light on how we can effect transformative change. Switch shows that successful changes follow a pattern, a pattern you can use to make the changes that matter to you.', 'https://books.google.com/books/content?id=QgzBqhbdlvUC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 322, 'http://play.google.com/books/reader?id=QgzBqhbdlvUC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
