INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('2Wo8J65noWQC', 'Hand Me Another Brick', array['Charles R. Swindoll'], 1998, 'Do others look to you for leadership? Do you face a major task or shoulder heavy responsibilities? Do you want to take your leadership skills to a higher level? When Nehemiah confronted the task of rebuilding Jerusalem''s wall, he was heartbroken by the damage he saw and nearly overwhelmed by the task that lay before him. Yet through the application of timeless leadership principles, Nehemiah completed this nearly impossible project, and laid a pattern for success which is just as valid for us today. Charles Swindoll brings his sensible and straightforward style to offer a deeply spiritual approach to the role of leader. Whatever the context, secular or ministerial, he demonstrates how to size up a task, organize and motivate a team, and respond to inevitable obstacles such as these: Unforeseen setbacks Unrelenting deadlines Criticism and outside resistance Personality conflicts Financial pressures and temptations The insights that Swindoll draws from Nehemiah''s wise administration will change your approach to leadership forever.', 'https://books.google.com/books/content?id=2Wo8J65noWQC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 250, 'http://play.google.com/books/reader?id=2Wo8J65noWQC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
