INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('a2gK_2OFiyUC', 'Sexual Homicide', array['John E. Douglas','Ann W. Burgess','Robert K. Ressler'], 2008, 'Who are the men committing the rising number of serial homicides in the U.S. -- and why do they kill? The increase in these violent crimes over the past decade has created an urgent need for more and better information about these men: their crime scene patterns, violent acts, and above all, their motivations for committing these shocking and repetitive murders. This authoritative book represents the data, findings, and implications of a long-term F.B.I.-sponsored study of serial sex killers. Specially trained F.B.I. agents examined thirty-six convicted, incarcerated sexual murderers to build a valuable new bank of information which reveals the world of the serial sexual killer in both quantitative and qualitative detail. Data was obtained from official psychiatric and criminal records, court transcripts, and prison reports, as well as from extensive interviews with the offenders themselves. Featured in this book is detailed information on the F.B.I.''s recently developed Violent Criminal Apprehension Program (VICAP) and a sample of an actual VICAP Crime Analysis Report Form.', 'https://books.google.com/books/content?id=a2gK_2OFiyUC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 256, 'http://play.google.com/books/reader?id=a2gK_2OFiyUC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
