INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('4rAYQfHk_0AC', 'Built to Sell', array['John Warrillow'], 2011, 'According to John Warrillow, the number one mistake entrepreneurs make is to build a business that relies too heavily on them. Thus, when the time comes to sell, buyers aren''t confident that the company-even if it''s profitable-can stand on its own. To illustrate this, Warrillow introduces us to a fictional small business owner named Alex who is struggling to sell his advertising agency. Alex turns to Ted, an entrepreneur and old family friend, who encourages Alex to pursue three criteria to make his business sellable: * Teachable: focus on products and services that you can teach employees to deliver. * Valuable: avoid price wars by specialising in doing one thing better than anyone else. * Repeatable: generate recurring revenue by engineering products that customers have to repurchase often.', 'https://books.google.com/books/content?id=4rAYQfHk_0AC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 146, 'http://play.google.com/books/reader?id=4rAYQfHk_0AC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
