         VALUES ('yorZCwAAQBAJ', 'Parenting from the Inside Out', array['Daniel J. Siegel','Mary Hartzell'], 2013, 'Explores the extent to which our childhood experiences shape the way we parent, drawing on new findings in neurobiology and attachment research and explaining how interpersonal relationships directly impact the development of the brain. Offers parents a step-by-step approach to forming a deeper understanding of their own life stories.', 'https://books.google.com/books/content?id=yorZCwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 338, 'http://play.google.com/books/reader?id=yorZCwAAQBAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
