INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('-6bs1tL8MtAC', '52 Little Lessons from It''s a Wonderful Life', array['Bob Welch'], 2012, 'If George and Mary Bailey are annual guests at your home every winter, you already know that It''s a Wonderful Life is more than just a holiday tradition--it''s a powerful reminder that our lives can change everyone around us, for better or worse. But what can this Christmas classic teach us about our everyday lives? 52 Little Lessons from It''s a Wonderful Life will change the way you think about this holiday staple, from the lightheartedness of George and Mary''s floor-parting dance to the poignancy of a community that rallies to save a desperate man, Bob Welch''s 52 Little Lessons from It''s a Wonderful Life will inspire you to live for the things that matter most. Welch invites us to revisit the defining lessons in Frank Capra''s 1946 classic and discover new dimensions of the film you''ve seen time and again, including: What can we all learn from Mary''s quiet contentedness? Can George''s selflessness make you rethink your own priorities? What impact do we have on the people around us? Join Welch for a close-up of the characters and themes that shape this timeless story of resilience and redemption. You''ll be reminded that life''s most important work is often the work we never planned to do, that God can use the most unlikely among us to get the job done, and that grace is the greatest gift we can possibly give. Discover why It''s a Wonderful Life is more than just a holiday tradition--it''s an inspiration for us to lead better lives, to become people of honor and integrity, and to recognize what really matters.', 'https://books.google.com/books/content?id=-6bs1tL8MtAC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 219, 'http://play.google.com/books/reader?id=-6bs1tL8MtAC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
