INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('6WGhDwAAQBAJ', 'Think and Grow Rich', array['Napoleon Hill'], 2019, 'Think and Grow Rich adalah karya fundamental sang penulis buku sukses legendaris, Napoleon Hill. Buku yang pertama kali diterbitkan tahun 1937 ini sekarang tetap sama ampuhnya—dan akan mengubah kehidupan Anda selamanya. Bisa dibilang mustahil menemukan motivator yang sama sekali tidak terpengaruh oleh karya Hill. Pengaruhnya bisa dilihat dalam tulisan-tulisan Dale Carnegie dan Norman Vincent Peale. Gaung dari prinsip-prinsip Hill juga bisa ditemukan dalam karya Mary Kay Ash, Ken Blanchard, Jack Canfield dan Mark Victor Hansen, John Gray, Brian Tracy, dan Dennis Waitley. Steven Covey, penulis The Seven Habits of Highly Effective People, sering kali menyampaikan pengaruh Napoleon Hill dalam karyanya. Selain itu, Anthony Robbins, yang boleh jadi merupakan motivator dan penulis buku motivasi paling sukses pada awal abad ke-21, menyebut Napoleon Hill sebagai pahlawannya. Ciri khas utama edisi asli Think and Grow Rich adalah dalam setiap bab Napoleon Hill mencantumkan contoh-contoh nyata. Hal itu masih dipertahankan dalam edisi ini, dan dilengkapi contoh-contoh baru serta contoh kasus-kasus modern yang bisa dengan jelas mendemonstrasikan bahwa semua prinsip Hill tetap bisa diaplikasikan, dan sampai saat ini masih membimbing orang menuju kesuksesan. Banyak kiat sukses yang Anda baca di berbagai bestseller lain berasal dari buku ini. Buktikan sendiri!', 'https://books.google.com/books/content?id=6WGhDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 406, 'http://play.google.com/books/reader?id=6WGhDwAAQBAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
