           ON CONFLICT DO NOTHING;
INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('MjP56I2tNu0C', 'Overcoming Body Dysmorphic Disorder', array['Fugen Neziroglu','Sony Khemlani-Patel','Melanie T. Santos'], 2012, 'In Overcoming Body Dysmorphic Disorder, nationally recognized anxiety experts present a complete program for overcoming a debilitating anxiety disorder called body dysmorphic disorder. People affected with this disorder have an extreme prooccupation with perceived defects in their physical features.', 'https://books.google.com/books/content?id=MjP56I2tNu0C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 182, 'http://play.google.com/books/reader?id=MjP56I2tNu0C&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
