INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('ESHHEQAAQBAJ', 'The Greatest Miracle in the World', array['Og Mandino'], 2026, 'For the millions who have embraced Og Mandino''s classic, The Greatest Salesman in the World, here is his new book, which contains the amazing Memorandum from God . . . to you. A great inspirational writer tells his greatest story—an amazing narrative that will hold you spellbound . . . as it reveals exciting new secrets for your personal happiness and success. Here is a simple but powerful story that will affect your thoughts and actions long after the final sentence has touched your heart. You will never forget: • The four simple rules that can help you perform a miracle in your life • The glass geranium that will break your heart • The dingy parking lot where Mandino''s life, and yours, begins again • The ragpicker who rescues humans after they quit on themselves • The secret of regaining the self-esteem you have lost “A work that will lift the mind and heart of every reader!”—Norman Vincent Peale', 'https://books.google.com/books/content?id=ESHHEQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 129, 'http://play.google.com/books/reader?id=ESHHEQAAQBAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
