INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('clJbtFss-XQC', 'The Children who Lived', array['Kathryn A. Markell','Marc A. Markell'], 2008, 'Harry Potter''s encounters with grief, as well as the grief experiences of other fictional characters, can be used by educators, counselors, and parents to help children and adolescents deal with their own loss issues. The Children Who Lived is a unique approach toward grief and loss in children. Focusing on fictional child and adolescent characters experiencing grief, this book uses classic tales and the Harry Potter books to help grieving children and adolescents. Included in the text and the companion CD are a number of activities, discussion questions, and games that could be used with grieving children and adolescents, based on the fictional characters in these books.', 'https://books.google.com/books/content?id=clJbtFss-XQC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 210, 'http://play.google.com/books/reader?id=clJbtFss-XQC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
