INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('1gl0-1GTOqQC', 'The Creative Process in the Individual', array['Thomas Troward'], 2007, 'Everything that happens, happens for a reason-or, more specifically, everything that happens is an effect of some cause that came before. This is the logical progress of physical existence. New Thought pioneer Thomas Troward, in The Creative Process in the Individual, demonstrates not only how this equation applies to all creation, but how it flows from the divine and relates to the metaphysical, as well as where the individual is placed within this schema. Comprehensively considering the spiritual and mundane aspects of such an existential question, Troward, in this 1915 classic, ultimately exposes how the individual can operate in concert with these laws in order to better his existence and more easily meet his spiritual goal: connecting with God. English judge, philosopher, and painter THOMAS TROWARD (1847-1916) lived most of his life in India, in the service of the imperial monarchy. Among his publications, many of which profoundly affected the New Thought Movement, are The Law and the Word, Bible Mystery and Meaning, and The Hidden Power and Other Papers Upon Mental Science.', 'https://books.google.com/books/content?id=1gl0-1GTOqQC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 81, 'http://play.google.com/books/reader?id=1gl0-1GTOqQC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
