INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('1xXoRdTTZpUC', 'The Road Less Travelled', array['Morgan Scott Peck'], 2012, '"Confronting and solving problems is a painful process which most of us attempt to avoid. Avoiding resolution results in greater pain and an inability to grow both mentally and spiritually. Drawing heavily on his own professional experience, Dr M. Scott Peck, a psychiatrist, suggests ways in which facing our difficulties - and suffering through the changes - can enable us to reach a higher level of self-understanding. He discusses the nature of loving relationships- how to distinguish dependency from love; how to become one''s own person and how to be a more sensitive parent. This is a book that can show you how to embrace reality and yet achieve serenity and a richer existence. Hugely influential, it has now sold over ten million copies - and has changed many people''s lives round the globe. It may change yours."', 'https://books.google.com/books/content?id=1xXoRdTTZpUC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 354, 'http://play.google.com/books/reader?id=1xXoRdTTZpUC&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
