INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('awEAEAAAQBAJ', 'LEADERS EAT LAST', array['Simon Sinek'], 2020, 'Para pemimpin adalah mereka yang maju lebih dulu mengadang bahaya. Mereka mengesampingkan kepentingan diri sendiri demi melindungi kita atau demi membawa kita ke masa depan. Para pemimpin sigap mengorbankan milik mereka demi menyelamatkan milik kita. Dan mereka tidak akan pernah mengorbankan milik kita untuk menyelamatkan milik mereka. Itulah arti menjadi pemimpin. Dalam organisasi yang sukses, para pemimpin hebat menciptakan lingkungan yang memungkinkan orang-orang secara alami bekerja sama untuk melakukan hal-hal luar biasa. Ketika kita merasa yakin bahwa mereka akan membuat kita aman, kita akan bekerja bahu-membahu di belakang mereka, berkarya tanpa lelah untuk mewujudkan visi mereka, dan dengan bangga mengikuti arah langkah mereka. Apakah Anda seorang pemimpin?', 'https://books.google.com/books/content?id=awEAEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 388, 'http://play.google.com/books/reader?id=awEAEAAAQBAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
