         VALUES ('cwE5tAEACAAJ', 'The Art of Public Speaking', array['Dale Carnagey','Joseph Berg Esenwein'], 2017, '"The Art of Public Speaking" is a must-read for any public speaker, supervisor, teacher, American citizen. Although public speaking has come a long way since this book was first published, this book provides the fundamentals that have been lost over time by some speakers.', 'https://books.google.com/books/content?id=cwE5tAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 324, 'http://play.google.com/books/reader?id=cwE5tAEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
