INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('oMKFvwEACAAJ', 'Journal', array['Jay Wilson'], 2018, 'This notebook is perfect for you and your needs. With 50-150 lined pages it has enough room for you to jot, write, and scribble all your notes, thoughts and secrets. Check out Jay Wilson on Amazon for more designs and books that will fit your every need.What are you waiting for?If you would like to submit ides for a notebook cover or would like to submit a photo, I do give credit for photos where I know the photographer. Send me an email at thatwriternamedjaywilson@gmail.com If you are the owner of a photo on one notebook and I have failed to credit you, send me an email and I will update the book to give you the rightful credit. Please accept my apology for using the image without giving credit. Thank you. Check out more poetry and writing on my instagram account. jay_wilson_the_writer', 'https://books.google.com/books/content?id=oMKFvwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 152, 'http://play.google.com/books/reader?id=oMKFvwEACAAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
