INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('BphPEAAAQBAJ', 'Five Lessons', array['Neville'], 2018, 'In this unparalleled master class, Neville Goddard provides his most direct, exquisitely clear lessons on using your mind to create the life you want. Features a bonus chapter by historian Mitch Horowitz. In 1948 the modern mystic Neville Goddard presented a groundbreaking series of lessons to Los Angeles students, which many consider the teacher''s clearest, most penetrating explanation of his methods of mental creativity. This special lesson plan, augmented with a bonus chapter by historian Mitch Horowitz, recreates Neville''s master class, preserving his words exactly as students heard them at the time. These five lessons, plus a question-and-answer section, are the plainest and most direct description of the master''s techniques, now in a handsome signature edition with revealing and useful bonus material.', 'https://books.google.com/books/content?id=BphPEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 226, 'http://play.google.com/books/reader?id=BphPEAAAQBAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
