INSERT INTO books (bookId, bookTitle, authors, publishDate, description, thumbnail, pageCount, bookLink)
         VALUES ('ygx-DwAAQBAJ', 'The Phone Addiction Workbook', array['Hilda Burke'], 2019, 'Stop scrolling and start living! Build healthier relationships between you, your smartphone and all your devices, including tips to reduce social media obsession, notification anxiety and other unhealthy habits.Your smartphone is a powerful device that has fundamentally changed your life—no doubt improving it in many ways. And while you don''t need to give up your smartphone completely, if your day to day is filled with endless, anxiety-inducing checking, swiping and liking, then you need this helpful, step-by-step workbook to take back control of your life.Phone addiction is similar to gambling addiction and substance abuse. Its consequences include stress, depression, insomnia, intimacy issues and more. Written by an experienced psychotherapist, couples therapist and former telecommunications industry insider, The Phone Addiction Workbook''s program offers the blueprint for understanding addictive behavior and how it controls you. Weekly charts, practical tips and interactive activities help you stop unhealthy behavior and make lasting change.', 'https://books.google.com/books/content?id=ygx-DwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 144, 'http://play.google.com/books/reader?id=ygx-DwAAQBAJ&hl=&as_pt=BOOKS&source=gbs_api') ON CONFLICT (bookId) DO NOTHING;
